// ── Wallet Provider SDK: the parts behind the methods ───────────────────

/// What an app that hasn't been given access is told when it proposes a transaction.
const NOT_CONNECTED: &str = "ask for access first (request_access), then propose it";

/// How often an app's balance reads may go to the chain (or the CLI).
const BALANCE_EVERY: std::time::Duration = std::time::Duration::from_secs(15);
/// The served reads' kind for the LEZ balance read (`lez_read`).
const LEZ_BALANCE_KEY: &str = "lez-balance";
/// How often `wallet`'s read (the CLI's accounts, then each public one's summary) is made again.
const WALLET_EVERY: std::time::Duration = std::time::Duration::from_secs(15);
/// How often `cli_accounts`'s read is made again.
const ACCOUNTS_EVERY: std::time::Duration = std::time::Duration::from_secs(15);
/// How often the registry's settings are read again.
const SETTINGS_EVERY: std::time::Duration = std::time::Duration::from_secs(60);
/// How often the faucet's state is read again.
const FAUCET_INFO_EVERY: std::time::Duration = std::time::Duration::from_secs(60);
/// What a faucet press answers (`pending`) while the names CLI's version is still being read.
const FAUCET_GETTING_READY: &str = "Getting ready to ask the faucet… the wallet is still reading which names CLI it runs.";

/// The app asking, as Basecamp names its credential: a module's name, or
/// `host` for the host itself (Basecamp, or `logosctl` driving the module).
/// A caller that can't be named, or a module that calls itself `host`, can't
/// ask the wallet for anything.
/// Why an approved program call wasn't sent: `problem`, the whole of it (for the Names app
/// only: it may name the person's accounts and balances), and where it came from.
struct CallFailure {
    problem: String,
    fault: Fault,
}

/// Where a call's failure came from. Only a fault in this wallet's own setup is told to the
/// app that asked, in words of its own; anything about the call or the person's money is not.
#[derive(Clone, Copy, PartialEq, Debug)]
enum Fault {
    /// The call, the chain, or the person's accounts: the app hears only that it wasn't sent.
    Call,
    /// The names tool is too old for this call.
    Outdated,
    /// The names tool or its wallet isn't set up (not found, not made, locked).
    Setup,
}

/// A program call whose root is one of the person's NFT programs: its sheet warns (so it needs the
/// tick), since the account that signs holds its NFTs of that program in its own actor.
const NFT_ROOT_WARNING: &str = "This is an NFT program: a call can send, print or burn the NFTs the account you choose holds in it.";

/// What the app that asked is told when its call wasn't sent (`request_status` `error`).
const CALL_NOT_SENT: &str = "the wallet couldn't send it";
const CALL_NEEDS_UPDATE: &str = "Names Wallet needs an update to send this";
const CALL_NOT_SET_UP: &str = "Names Wallet isn't set up to send this yet";

impl CallFailure {
    fn call(problem: String) -> Self {
        CallFailure { problem, fault: Fault::Call }
    }
    fn setup(problem: String) -> Self {
        CallFailure { problem, fault: Fault::Setup }
    }
    fn app_reason(&self) -> &'static str {
        match self.fault {
            Fault::Call => CALL_NOT_SENT,
            Fault::Outdated => CALL_NEEDS_UPDATE,
            Fault::Setup => CALL_NOT_SET_UP,
        }
    }
}

fn asking_app() -> Result<String, String> {
    match calling() {
        logos_rust_sdk::LogosCaller::Module { name, .. } if name != "host" => provider::app_name(&name),
        logos_rust_sdk::LogosCaller::HostAnchor => Ok("host".to_owned()),
        other => Err(format!("the wallet can't tell which app is asking ({}), so it refuses", other.describe_for_human())),
    }
}

/// Whether `choice` (from `wallet_choices`) may be used for a request of `kind`:
/// a payment comes from an account the CLI pays from, a call is signed by a
/// public account, and access may be given to any.
fn offered_for(kind: &str, choice: &Value) -> bool {
    match kind {
        provider::TRANSFER => choice["pays"] == true,
        provider::CALL => choice["account_kind"] == "public",
        _ => true,
    }
}

/// `public` or `private`, for an account written `Public/...` or `Private/...`.
fn kind_of(account: &str) -> &'static str {
    if account.starts_with("Private/") {
        "private"
    } else {
        "public"
    }
}

impl Names {
    /// The provider's store, read from disk the first time, with requests
    /// nobody answered in time expired.
    fn store(&mut self) -> &mut provider::Store {
        if self.provider.is_none() {
            let path = self.provider_path.clone().or_else(|| config_dir().map(|dir| dir.join("provider.json")));
            self.provider = Some(provider::Store::load(path));
        }
        let store = self.provider.as_mut().expect("the store was just loaded");
        if store.sweep(provider::now_ms()) {
            store.save();
        }
        store
    }

    /// `request_access(_with)`: asks for access (or answers the grant or the waiting request),
    /// with an account the sheet ticks first (`hint`), never one given without the person's tick.
    fn access_asked(&mut self, reason: &str, hint: Option<String>) -> Result<Value, String> {
        let app = asking_app()?;
        let now = provider::now_ms();
        let store = self.store();
        let granted = store.granted(&app);
        // An app that already sees some accounts and names one it doesn't see asks to ADD that one:
        // a request, not "approved" (which the app couldn't act on: LEZ Bridge's receive into a
        // public account it wasn't given waited forever, M2 2026-11-14).
        let wants_new = hint.as_ref().is_some_and(|h| !granted.iter().any(|g| g == h));
        if !granted.is_empty() && !wants_new {
            return Ok(json!({ "request": null, "kind": provider::CONNECT, "state": "approved", "accounts": granted }));
        }
        if let Some(waiting) = store.requests.iter().find(|r| r["app"] == app.as_str() && r["kind"] == provider::CONNECT && r["state"] == "pending") {
            return Ok(provider::app_view(waiting));
        }
        // With no wallet on this network the person has nothing to give: a plain refusal,
        // never a request that waits unseen behind the Welcome screen.
        if !self.home_has_wallet() {
            let net = self.net.shown();
            return Err(format!(
                "the Names wallet has no wallet on {} yet; the person creates it in the Names app first, then the app asks again",
                net["version"].as_str().unwrap_or("this network")
            ));
        }
        // Adding to a grant: only an account the wallet holds (the sheet could offer nothing else).
        let adding = !granted.is_empty();
        if let Some(hint) = hint.as_deref().filter(|_| adding) {
            if !self.wallet_holds(hint)? {
                return Err(format!("the Names wallet doesn't hold {hint}, so it can't be added to this app's access"));
            }
        }
        let store = self.store();
        let mut request = provider::connect_request(&app, reason, now)?;
        if let Some(hint) = hint {
            request["account_hint"] = json!(hint);
        }
        if adding {
            // The sheet asks for that one account only; approving it leaves the others as they are.
            request["adding"] = json!(true);
        }
        let view = provider::app_view(&request);
        store.add(request, now)?;
        store.save();
        Ok(view)
    }

    /// Whether `account` is one an access request can offer from the wallet now (its main
    /// public and private accounts, and its other public accounts): the background list first,
    /// the wallet itself when that doesn't have it.
    fn wallet_holds(&self, account: &str) -> Result<bool, String> {
        if self.wallet_choices(&self.publics_read_lately()).iter().any(|choice| choice["account"] == account) {
            return Ok(true);
        }
        let held = self.held()?;
        Ok(self.wallet_choices(&held.public).iter().any(|choice| choice["account"] == account))
    }

    /// Adds a transaction request from `app`, which must have been given access.
    /// Whether the asking app is really published by the LNS name its package names, as the
    /// Program Registry checks it (`verify_app`, docs/APPS.md in lez-program-registry):
    /// `{status, publisher, module, version, record}`, `{status: "unavailable"}` when the
    /// registry module isn't installed or couldn't say, `{status: "checking"}` while it is being
    /// asked, or null for Basecamp itself. An answer is kept for a minute per app.
    fn publisher_of(&mut self, app: &str) -> Value {
        if app == "host" {
            return Value::Null;
        }
        let now = now();
        if let Some((answer, at)) = self.publishers.get(app) {
            if now.saturating_sub(*at) < 60 {
                return answer.clone();
            }
        }
        match program_registry::publisher_state(app) {
            Looked::Known(answer) => {
                self.publishers.insert(app.to_owned(), (answer.clone(), now));
                answer
            }
            // Asked, no answer yet (a few seconds): the sheet can't be approved until it is back.
            Looked::Checking => json!({ "status": "checking" }),
            // The registry isn't installed or couldn't say: said as such, asked again later.
            Looked::Missing => json!({ "status": "unavailable" }),
        }
    }

    /// What the Program Registry is still being asked about for `request`: who publishes its app,
    /// or a program it names (its call's, its declaration's, its token's). Nothing is approved
    /// until those answers are back (M-2): one may be a warning the sheet doesn't show yet.
    fn still_checking(&mut self, request: &Value) -> Option<String> {
        let app = request["app"].as_str().unwrap_or_default().to_owned();
        if self.publisher_of(&app)["status"] == "checking" {
            return Some(format!("who publishes {app}"));
        }
        let mut programs: Vec<&str> = request["programs"].as_array().map(Vec::as_slice).unwrap_or_default().iter().filter_map(Value::as_str).collect();
        programs.extend(["program", "token_program"].iter().filter_map(|key| request[*key].as_str()));
        programs.into_iter().find(|program| program_registry::label_state(program) == Looked::Checking).map(|program| format!("program {program}"))
    }

    fn queue(&mut self, app: &str, mut request: Value, now: u64) -> Result<Value, String> {
        // A transfer or a call is for the zone in use when it is asked, and is approved
        // only there: the same account ID is another account on another zone.
        if request["kind"] == provider::TRANSFER || request["kind"] == provider::CALL {
            let zones = self.zones_now();
            request["zone"] = json!(zones.current_id());
            request["zone_name"] = json!(zones.zone().name);
            request["zone_channel"] = json!(zones.zone().channel);
            request["network"] = json!(self.net.id());
        }
        let store = self.store();
        if store.granted(app).is_empty() {
            return Err(NOT_CONNECTED.to_owned());
        }
        let view = provider::app_view(&request);
        store.add(request, now)?;
        store.save();
        Ok(view)
    }

    /// The accounts a request may use, all in the names CLI's wallet: its main
    /// public and private accounts, which pay (`names setup` saved them), and
    /// its other public accounts `others`, which can sign program calls.
    fn wallet_choices(&self, others: &[AccountId]) -> Vec<Value> {
        let mut choices = Vec::new();
        let wallet = self.resolve_wallet(self.cli_wallet.as_deref()).filter(|dir| dir.join(cli::STORAGE_FILE).is_file());
        let Some(wallet) = wallet else { return choices };
        for (which, private, label) in [("public", false, "Names wallet, main public account"), ("private", true, "Names wallet, private account")] {
            if let Some(id) = cli::saved_account(&wallet, which).and_then(|id| registry::parse_account(&id).ok()) {
                choices.push(json!({ "account": provider::account_written(private, &id), "account_kind": which, "pays": true, "label": label }));
            }
        }
        for id in others.iter().take(MAX_WALLET_ACCOUNTS) {
            let account = provider::account_written(false, id);
            if !choices.iter().any(|choice| choice["account"] == account.as_str()) {
                choices.push(json!({ "account": account, "account_kind": "public", "pays": false, "label": "Names wallet, public account" }));
            }
        }
        choices
    }

    /// The wallet's public accounts as last read in the background (see
    /// `pending_requests`); empty until the first read ends.
    fn publics_read_lately(&self) -> Vec<AccountId> {
        let Ok(setup) = self.cli_setup() else { return Vec::new() };
        let read = self.read_in_background(self.zone_key("provider:publics"), std::time::Duration::from_secs(30), move || {
            wallet::accounts(&setup).map(|held| json!(held.public.iter().map(registry::account_text).collect::<Vec<_>>()))
        });
        read["value"]
            .as_array()
            .map(Vec::as_slice)
            .unwrap_or_default()
            .iter()
            .filter_map(|id| registry::parse_account(id.as_str()?).ok())
            .collect()
    }

    /// Approves a pending request with the account(s) the person chose.
    /// Nothing is signed or sent unless the request is pending, the account
    /// is one of its choices, and the existing payment or signing path
    /// accepts it.
    fn approve(&mut self, id: &str, account: &str) -> Result<Value, String> {
        let now = provider::now_ms();
        let request = self.store().get(id).cloned().ok_or("there is no such request")?;
        if request["state"] != "pending" {
            return Err(format!("that request is {} already", request["state"].as_str().unwrap_or("decided")));
        }
        if let Some(what) = self.still_checking(&request) {
            return Err(format!("still checking {what} with the Program Registry; try again in a few seconds"));
        }
        let kind = request["kind"].as_str().unwrap_or_default().to_owned();
        let app = request["app"].as_str().unwrap_or_default().to_owned();
        if matches!(kind.as_str(), provider::PRIVATE_CALL | provider::SECRET | provider::TOKEN_SOURCE) {
            return self.approve_private(id, &request, account);
        }
        if matches!(kind.as_str(), provider_public::RELAYED_CALL | provider_public::PROGRAMS) {
            return self.approve_public(id, &request, account);
        }
        if kind == provider::TRANSFER || kind == provider::CALL {
            // Stays pending: the person can switch zones and approve it, or reject it.
            self.asked_here(&request)?;
        }
        if kind == provider::CALL {
            // A token program set (or a bridge read) since it was asked is refused now too.
            let program = registry::parse_account(request["program"].as_str().unwrap_or_default())?;
            self.call_root_allowed(&program)?;
        }
        let chosen: Vec<String> = account
            .split(',')
            .map(str::trim)
            .filter(|account| !account.is_empty())
            .map(|account| provider::account_ref(account).map(|(private, id)| provider::account_written(private, &id)))
            .collect::<Result<_, _>>()?;
        if chosen.is_empty() {
            return Err("choose an account".to_owned());
        }
        if kind != provider::CONNECT && chosen.len() != 1 {
            return Err("choose one account".to_owned());
        }
        // A request to add an account is checked again now: only that account, and only while
        // the app still has the access it is added to (taken back since, it can ask again).
        if request["adding"] == true {
            let hint = request["account_hint"].as_str().unwrap_or_default();
            if chosen.len() != 1 || chosen[0] != hint {
                return Err(format!("this request only asks for {hint}"));
            }
            if self.store().granted(&app).is_empty() {
                let store = self.store();
                if let Some(stored) = store.get_mut(id) {
                    stored["state"] = json!("rejected");
                    stored["decided"] = json!(now);
                    stored["error"] = json!("this app's access was taken back after it asked; it can ask again");
                }
                store.save();
                return Err("this app's access was taken back after it asked, so there is nothing to add to; it can ask again".to_owned());
            }
        }
        // Checked against the wallet itself, not a list read earlier: a call
        // must be signed by an account the CLI's wallet holds now.
        let others = if kind == provider::TRANSFER { Vec::new() } else { self.held().map(|held| held.public).unwrap_or_default() };
        let choices = self.wallet_choices(&others);
        let offered: Vec<&Value> = choices.iter().filter(|choice| offered_for(&kind, choice)).collect();
        if kind == provider::CALL && !others.iter().any(|id| provider::account_written(false, id) == chosen[0]) {
            return Err(format!("{} isn't an account the names wallet can sign with now", chosen[0]));
        }
        if let Some(stray) = chosen.iter().find(|wanted| !offered.iter().any(|choice| choice["account"] == wanted.as_str())) {
            return Err(format!("{stray} isn't one of the accounts this request can use"));
        }
        let mut outcome = json!({ "decided": now, "account": if kind == provider::CONNECT { Value::Null } else { json!(chosen[0]) } });
        let failure = match kind.as_str() {
            provider::CONNECT => {
                let granted = self.store().grant(&app, &chosen, now)?;
                outcome["state"] = json!("approved");
                outcome["granted"] = json!(granted);
                None
            }
            provider::TRANSFER => {
                // A payment that didn't start sent nothing: the request stays pending.
                let job = self.provider_transfer(&request, &chosen[0])?;
                outcome["state"] = json!("running");
                outcome["job"] = job["id"].clone();
                None
            }
            provider::CALL => {
                let sent = self.provider_call(&request, &chosen[0]);
                // The History shows each call sent for an app, and why one failed (Names only).
                let mut line = json!({ "kind": "app_call", "chain": "lez", "app": app, "from": chosen[0], "program": request["program"] });
                let failure = match sent {
                    Ok(tx) => {
                        outcome["state"] = json!("done");
                        outcome["tx"] = json!(tx);
                        line["state"] = json!("done");
                        line["tx"] = json!(tx);
                        None
                    }
                    // A send that failed may still have gone through, so it is
                    // never offered again: the request ends failed. The app is told a reason
                    // only when it is about this wallet's own setup (CallFailure::app_reason);
                    // the whole of it, which may name balances, stays with the Names app.
                    Err(failed) => {
                        outcome["state"] = json!("failed");
                        outcome["error"] = json!(failed.app_reason());
                        outcome["problem"] = json!(failed.problem);
                        line["state"] = json!("failed");
                        line["problem"] = json!(failed.problem);
                        Some(failed.problem)
                    }
                };
                if let Some(dir) = config_dir() {
                    activity::add(&dir, now, activity::in_zone(line, &self.zones.current_id()));
                }
                failure
            }
            _ => return Err("this request can't be approved".to_owned()),
        };
        let store = self.store();
        let view = match store.get_mut(id) {
            Some(stored) => {
                for (key, value) in outcome.as_object().into_iter().flatten() {
                    stored[key.as_str()] = value.clone();
                }
                if kind == provider::CALL {
                    // The instruction was only kept to be sent.
                    if let Some(fields) = stored.as_object_mut() {
                        fields.remove("instruction");
                    }
                }
                merged(provider::app_view(stored), &json!({ "job": stored["job"] }))
            }
            None => outcome,
        };
        store.save();
        match failure {
            Some(error) => Err(error),
            None => Ok(view),
        }
    }

    /// Starts an approved transfer through the names CLI, as `cli_pay` and
    /// `cli_pay_account` would: a name is paid with `names pay` (from the
    /// public account with `--from`), an account with `auth-transfer send`.
    fn provider_transfer(&self, request: &Value, account: &str) -> Result<Value, String> {
        let (private, _) = provider::account_ref(account)?;
        let amount = request["amount"].as_str().unwrap_or_default().to_owned();
        let destination = request["destination"].as_str().unwrap_or_default().to_owned();
        if let Some(definition) = provider::token_of(request) {
            // The prompt named one token program; nothing is sent with another.
            let program = self.token_program_set()?;
            if request["token_program"] != registry::account_text(&program).as_str() {
                return Err("the token program has changed since this was asked; reject it, and the app can ask again".to_owned());
            }
            let command = cli::token_send_args(&program, &registry::account_text(&definition), &amount, &destination, private, false)?;
            return self.wallet_job("token_send", |_| Ok(command));
        }
        match cli::pay_to(&destination)? {
            cli::PayTo::Name(name) => {
                let command = if private {
                    cli::pay_args(&name, &amount)?
                } else {
                    cli::pay_from_public_args(&self.cli_setup()?, &name, &amount)?
                };
                let started = parsed_reply(&self.cli_job(&name, "pay", |_, _, _| Ok((command, None, Value::Null))))?;
                Ok(started)
            }
            cli::PayTo::Account(_) => self.wallet_job("pay_account", |setup| cli::pay_account_args(setup, &destination, &amount, private)),
        }
    }

    /// Signs and sends an approved program call through the names CLI, the
    /// way the module sends its own registry changes (`names module send`),
    /// with the call's program in place of the registry: the CLI tries it
    /// against the chain first, sizes its gas, signs, sends and waits for its
    /// block. The signer's own actor of the program comes first, then the
    /// accounts the request reaches. Returns the transaction hash.
    fn provider_call(&self, request: &Value, account: &str) -> Result<String, CallFailure> {
        let call = CallFailure::call;
        let (_, signer) = provider::account_ref(account).map_err(call)?;
        let program = registry::parse_account(request["program"].as_str().unwrap_or_default()).map_err(call)?;
        let message = registry::unhex(request["instruction"].as_str().unwrap_or_default()).map_err(call)?;
        if message.is_empty() {
            return Err(call("this request has nothing to send".to_owned()));
        }
        let mut mentions = vec![Mention { account: signer, program, seed: None, signs: true }];
        let mut reads_clock = false;
        for reached in provider::stored_reached(request).map_err(call)? {
            let account = if reached.account == provider::SIGNER { signer } else { registry::parse_account(&reached.account).map_err(call)? };
            // Another program's account (the network clock) is only read: never signed, and never
            // the chosen account, whose signature would authorize that program on it.
            if reached.reads && account == signer {
                return Err(call("this call reads another program's data on the account you chose; nothing was sent".to_owned()));
            }
            // The chosen account's LEZ is given to a program only as `signer`, which the prompt
            // says: written as its ID it would be given too (the account signs, and LEZ 0.4
            // authorizes by account), under a prompt that said the call can't move it.
            if reached.balance && reached.account != provider::SIGNER && account == signer {
                return Err(call("this call lists the account you chose by its ID for its LEZ, which the prompt didn't say it may move; reject it, and the app can ask again with \"signer\". Nothing was sent.".to_owned()));
            }
            reads_clock |= reached.reads;
            mentions.push(Mention {
                account,
                program: reached.program(&program),
                seed: reached.seed,
                signs: !reached.reads && account == signer && reached.seed.is_none(),
            });
        }
        let change = Change { message, mentions, signer, needs: 0, extra: Value::Null };
        // The wallet's own setup: the app may be told so (CallFailure::app_reason).
        let mut setup = self.cli_setup().map_err(CallFailure::setup)?;
        setup.wallet_ready().map_err(CallFailure::setup)?;
        if reads_clock {
            // A CLI before 0.18 can't try a call that reads the clock, so it would refuse it
            // with a bare "Program violated execution rules"; say what to do instead.
            if let Ok(line) = self.cli_line(&setup.program) {
                if !cli_reads_clock(&line) {
                    return Err(CallFailure {
                        problem: format!("this call reads the network clock, which needs the names tool 0.18 or later (this one says {line}); nothing was sent"),
                        fault: Fault::Outdated,
                    });
                }
            }
        }
        setup.registry = Some(registry::account_text(&program));
        wallet::send(&setup, &change).map_err(call)
    }

    /// Ends the requests whose payment job has ended. The app that asked is
    /// told only whether it went through; the CLI's own words, which may name
    /// the person's accounts and balances, go only to the Names app.
    fn provider_refresh(&mut self) {
        let private_changed = self.private_refresh();
        let jobs = self.jobs().ok();
        let now = provider::now_ms();
        let store = self.store();
        let mut changed = private_changed;
        let mut tokens_moved = false;
        for request in store.requests.iter_mut().filter(|request| request["state"] == "running") {
            let state = request["job"].as_str().and_then(|job| jobs.as_ref()?.state(job).ok());
            let ended = match &state {
                None => Some((false, "the payment's record is gone; check the balance".to_owned())),
                Some(state) if state["state"] == "done" => Some((true, String::new())),
                Some(state) if state["state"] == "failed" => {
                    let log = state["log_tail"].as_str().unwrap_or_default();
                    Some((false, crate::text::clean_remote(&cli::failure_cause(log), 300)))
                }
                _ => None,
            };
            if let Some((done, problem)) = ended {
                request["state"] = json!(if done { "done" } else { "failed" });
                request["finished"] = json!(now);
                if !done {
                    request["error"] = json!(if request["kind"] == provider::PRIVATE_CALL {
                        "the private call didn't go through"
                    } else {
                        "the payment didn't go through"
                    });
                    request["problem"] = json!(problem);
                }
                if request["kind"] == provider::PRIVATE_CALL {
                    // A private call (a bridge's private burn, a private claim) changes what the
                    // account holds: the token reads made before it are not shown again (wallet-1120).
                    tokens_moved = true;
                    // The message and the simulation were only kept to be sent and shown.
                    if let Some(fields) = request.as_object_mut() {
                        fields.remove("message");
                    }
                }
                tokens_moved |= request["asset_kind"] == provider::TOKEN;
                changed = true;
            }
        }
        if changed {
            store.save();
        }
        if tokens_moved {
            self.forget_tokens();
        }
    }

    /// One account's balance for the app it was given to, read in the background.
    fn granted_balance(&self, account: &str) -> Value {
        let unreadable = |why: &str| json!({ "account": account, "account_kind": kind_of(account), "balance": null, "updating": false, "error": why });
        let Ok((private, id)) = provider::account_ref(account) else {
            return unreadable("not an account");
        };
        let read = if private {
            // Only the names CLI's own private account can be read here.
            let setup = match self.cli_setup() {
                Ok(setup) if cli::default_private(&setup).ok().as_deref() == Some(registry::account_text(&id).as_str()) => setup,
                _ => return unreadable("this private account's balance can't be read on this computer"),
            };
            let read = self.read_in_background(self.zone_key("provider:cli_balance"), BALANCE_EVERY, move || cli::run_balance(&setup));
            let balance = read["value"]["balance"].clone();
            merged(read, &json!({ "value": balance }))
        } else {
            let registry = Registry::new(&self.sequencer, self.program.unwrap_or([0; 32]));
            self.read_in_background(self.zone_key(&format!("provider:balance:{}", registry::account_text(&id))), BALANCE_EVERY, move || {
                registry.balance(&id).map(|balance| json!(balance.to_string()))
            })
        };
        json!({
            "account": account,
            "account_kind": kind_of(account),
            "balance": read["value"],
            "updating": read["updating"],
            "error": read["error"],
        })
    }

    /// The background reads whose key starts with `prefix` are made afresh on their next call:
    /// their values are kept (shown meanwhile), and a read under way is dropped when it ends.
    fn refresh_reads(&self, prefix: &str) {
        if let Ok(mut reads) = self.board_reads.lock() {
            for (_, read) in reads.iter_mut().filter(|(key, _)| key.starts_with(prefix)) {
                read.fetched = None;
                read.updating = false;
                read.reading = 0;
            }
        }
    }

    /// Answers at once with the last value `fetch` gave for `key`, `{value,
    /// updating, error}`, and starts a newer read on its own thread unless
    /// one is on the way or the last ended less than `every` ago.
    fn read_in_background(&self, key: String, every: std::time::Duration, fetch: impl FnOnce() -> Result<Value, String> + Send + 'static) -> Value {
        let mut reads = self.board_reads.lock().expect("the board reads lock");
        let read = reads.entry(key.clone()).or_default();
        if !read.updating && read.fetched.is_none_or(|at| at.elapsed() >= every) {
            read.updating = true;
            let reading = next_reading();
            read.reading = reading;
            let reads = std::sync::Arc::clone(&self.board_reads);
            std::thread::spawn(move || {
                let fetched = fetch();
                let mut reads = reads.lock().expect("the board reads lock");
                // Forgotten since it started (a send, a claim, another wallet): dropped.
                let Some(read) = reads.get_mut(&key).filter(|read| read.reading == reading) else { return };
                read.updating = false;
                read.fetched = Some(std::time::Instant::now());
                match fetched {
                    Ok(value) => {
                        read.value = Some(value);
                        read.error = None;
                    }
                    Err(error) => read.error = Some(error),
                }
            });
        }
        json!({ "value": read.value, "updating": read.updating, "error": read.error })
    }

    // ── Tokens ──────────────────────────────────────────────────────────

    /// The token program the token methods use, or why there is none.
    fn token_program_set(&self) -> Result<AccountId, String> {
        self.token_program.ok_or_else(|| {
            "no token program is set: enter its program ID under Wallet, Add a token (no token program runs on the public testnet yet)".to_owned()
        })
    }

    /// The wallet's tokens and pending credits as last read, `{value:
    /// {holdings, pending}, updating, error}`, with a newer read started in
    /// the background when the last is older than `TOKENS_EVERY`. Kept per
    /// wallet and token program.
    fn token_read(&self) -> Result<(AccountId, Value), String> {
        let program = self.token_program_set()?;
        let setup = self.cli_setup()?;
        setup.wallet_ready()?;
        let key = format!("{TOKENS_KEY}{}:{}", registry::account_text(&program), setup.wallet.display());
        let read = self.read_in_background(key, TOKENS_EVERY, move || cli::run_token_list(&setup, &program));
        Ok((program, read))
    }

    /// Drops the token reads, after a token job ended or the program changed.
    fn forget_tokens(&self) {
        self.board_reads.lock().expect("the board reads lock").retain(|key, _| !key.starts_with(TOKENS_KEY));
    }

    /// What the token `definition` of `program` is, read through the CLI and
    /// kept for `READ_FRESH`.
    fn token_info_of(&mut self, program: &AccountId, definition: &AccountId) -> Result<Value, String> {
        let key = (*program, *definition);
        if let Some((info, at)) = self.token_info.get(&key) {
            if at.elapsed() < READ_FRESH {
                return Ok(info.clone());
            }
        }
        let info = cli::run_token_info(&self.cli_setup()?, program, definition)?;
        if self.token_info.len() >= MAX_CACHED {
            self.token_info.retain(|_, (_, at)| at.elapsed() < READ_FRESH);
            if self.token_info.len() >= MAX_CACHED {
                self.token_info.clear();
            }
        }
        self.token_info.insert(key, (info.clone(), std::time::Instant::now()));
        Ok(info)
    }
}

/// How long a private call's plan (the CLI's simulation) may take: it reads the programs'
/// bytecode and catches the wallet up with the chain.
const PRIVATE_PLAN_PATIENCE: std::time::Duration = std::time::Duration::from_secs(240);
/// How long the account-scheme question waits for the CLI.
const SCHEME_PATIENCE: std::time::Duration = std::time::Duration::from_secs(20);
/// How long `app_secret` waits for the CLI.
const SECRET_PATIENCE: std::time::Duration = std::time::Duration::from_secs(60);

impl Names {
    /// The token programs the wallet reads holdings of: its own and the token sources'.
    fn known_token_programs(&mut self) -> Vec<String> {
        let mut programs: Vec<String> = self.token_program.iter().map(registry::account_text).collect();
        for source in &self.store().private.token_sources {
            if let Some(program) = source["token_program"].as_str() {
                if !programs.iter().any(|known| known == program) {
                    programs.push(program.to_owned());
                }
            }
        }
        programs
    }

    /// Adds a request of any kind from `app`, which must have been given access.
    fn queue_any(&mut self, app: &str, request: Value, now: u64) -> Result<Value, String> {
        let store = self.store();
        if store.granted(app).is_empty() && request["kind"] != provider::TOKEN_SOURCE {
            return Err(NOT_CONNECTED.to_owned());
        }
        let view = provider::app_view(&request);
        store.add(request, now)?;
        store.save();
        Ok(view)
    }

    /// `app_secret`: the values, or the request that asks the person first.
    fn secret_values(&mut self, account: &str, scope: &str, context_hex: &str, tag: &str, first: i64, count: i64) -> Result<Value, String> {
        let app = asking_app()?;
        let (private, id) = provider::account_ref(account)?;
        let account = provider::account_written(private, &id);
        let context = if context_hex.trim().is_empty() { Vec::new() } else { registry::unhex(context_hex.trim()).map_err(|_| "the context is hex".to_owned())? };
        let first = u64::try_from(first).map_err(|_| "the first index is 0 or more".to_owned())?;
        let count = u64::try_from(count).map_err(|_| "the count is 1 to 64".to_owned())?;
        let ask = app_secret::Ask::new(&app, scope.trim(), context, tag.trim(), first, count)?;
        let now = provider::now_ms();
        // An exit's values say where tokens go on Ethereum: the context is read (a context that
        // doesn't read is refused, never granted), and an address the person hasn't approved for
        // this app and account asks them first, with the address shown (exit_recipient.rs).
        let exit = if ask.scope == exit_recipient::EXIT_SCOPE { Some(exit_recipient::decode(&ask.context)?) } else { None };
        let wallet_dir = self.wallet_dir_of(self.net);
        let exit_new = exit.as_ref().filter(|e| {
            !wallet_dir.as_deref().is_some_and(|dir| exit_recipient::is_approved(dir, &app, &account, &exit_recipient::address_text(&e.recipient)))
        });
        let store = self.store();
        if !store.granted(&app).contains(&account) {
            return Err(format!("{account} wasn't given to this app; ask for it with request_access"));
        }
        if !store.private.has_secret(&app, &account, &ask.scope) || exit_new.is_some() {
            let recipient = exit_new.map(|e| exit_recipient::address_text(&e.recipient));
            let waiting = store.requests.iter().find(|r| {
                r["kind"] == provider::SECRET && r["state"] == "pending" && r["app"] == app.as_str() && r["account"] == account.as_str() && r["scope"] == ask.scope.as_str()
                    && r["exit"]["recipient"].as_str() == recipient.as_deref()
            });
            if let Some(waiting) = waiting {
                return Ok(json!({ "granted": false, "request": provider::app_view(waiting) }));
            }
            let mut request = provider_private::secret_request(&app, &account, &ask.scope, "", now)?;
            if let Some(exit) = exit_new {
                request["exit"] = exit_recipient::sheet(exit);
            }
            // An imported account: said once, on the first secret request for it from any app.
            if self.account_imported(&account) == Some(true) {
                let store = self.store();
                let first = !store.private.secrets.values().filter_map(Value::as_array).flatten().any(|g| g["account"] == account.as_str())
                    && !store.requests.iter().any(|r| r["kind"] == provider::SECRET && r["account"] == account.as_str() && r["imported"] == true);
                provider_private::mark_imported(&mut request, private, first);
            }
            let view = provider::app_view(&request);
            let store = self.store();
            store.add(request, now)?;
            store.save();
            return Ok(json!({ "granted": false, "request": view }));
        }
        // Each call runs the CLI, so an app is bounded per hour.
        let calls = self.secret_calls.entry(app.clone()).or_default();
        calls.retain(|at| now.saturating_sub(*at) < 60 * 60 * 1000);
        if calls.len() >= provider_private::MAX_SECRET_CALLS_PER_HOUR {
            return Err("this app has asked for secrets too often in the last hour; try again later".to_owned());
        }
        calls.push(now);
        let setup = self.cli_setup()?;
        setup.wallet_ready()?;
        // The scheme pinned for this account at its first values (any app): the tool must use it.
        // Kept in the wallet folder (provider_private::PINS_FILE), falling back to the grant rows a
        // build before that kept it in. A grant from before pinning: `unknown`, both sets asked.
        let wallet_dir = self.wallet_dir_of(self.net);
        let mut pinned = wallet_dir.as_deref().and_then(|dir| provider_private::read_pin(dir, &account)).or_else(|| self.store().private.pinned_scheme(&account));
        if pinned.is_none() && self.store().private.has_legacy_grant(&account) {
            pinned = Some(provider_private::SCHEME_UNKNOWN.to_owned());
            if let Some(dir) = &wallet_dir {
                provider_private::write_pin(dir, &account, provider_private::SCHEME_UNKNOWN)?;
            }
        }
        let unknown = pinned.as_deref() == Some(provider_private::SCHEME_UNKNOWN);
        let mut input = json!({
            "app": ask.app, "account": account, "scope": ask.scope, "context": registry::hex(&ask.context),
            "tag": ask.tag, "first": ask.first, "count": ask.count,
        });
        if let Some(scheme) = &pinned {
            input["scheme"] = json!(if unknown { "both" } else { scheme.as_str() });
        }
        let what = if ask.scope.starts_with("RFP022/deposit") { "deposit keys" } else { "the values this app asks for" };
        // The tool's words never reach the screen (they named key trees and CLI errors): a plain line.
        let output = cli::run_with_input(&setup, vec!["module".into(), "app-secret".into()], &input.to_string(), SECRET_PATIENCE)
            .map_err(|why| provider_private::secret_failure(what, &account, &why))?;
        let answer: Value = serde_json::from_str(cli::last_line(&output)).map_err(|_| provider_private::secret_failure(what, &account, ""))?;
        let values: Vec<String> = answer["values"].as_array().map(Vec::as_slice).unwrap_or_default().iter().filter_map(|v| v.as_str().map(str::to_owned)).collect();
        if values.len() as u64 != ask.count || answer["account"] != account.as_str() || values.iter().any(|v| v.len() != 64) {
            return Err(provider_private::secret_failure(what, &account, ""));
        }
        // A tool that doesn't name its scheme predates imported accounts' phrase values: it gives an
        // imported account values from the imported key, which the phrase can't make again. Its
        // answer is taken only for an account known to be a phrase account (review 2026-11-18).
        let scheme = match answer["scheme"].as_str() {
            Some(scheme @ (app_secret::SCHEME_IMPORTED | app_secret::SCHEME_PHRASE)) => scheme.to_owned(),
            _ if pinned.as_deref() == Some(app_secret::SCHEME_IMPORTED) || unknown => return Err(provider_private::older_tool_for_imported(what, &account)),
            _ => match self.account_imported(&account) {
                Some(false) => app_secret::SCHEME_PHRASE.to_owned(),
                Some(true) => return Err(provider_private::older_tool_for_imported(what, &account)),
                None => return Err(provider_private::older_tool(what, &account)),
            },
        };
        // Pinned once; a tool that answers another way than the pin is refused, never handed out.
        if !unknown && pinned.as_ref().is_some_and(|p| *p != scheme) {
            return Err(provider_private::other_scheme(what, &account));
        }
        // An unknown pin: the other scheme's values too, which the app matches against what it
        // stored (it never pins: what it stored decides, record by record).
        let other: Option<Vec<String>> = if unknown {
            let o: Vec<String> = answer["other_values"].as_array().map(Vec::as_slice).unwrap_or_default().iter().filter_map(|v| v.as_str().map(str::to_owned)).collect();
            if o.len() as u64 != ask.count || o.iter().any(|v| v.len() != 64) || answer["other_scheme"].as_str().is_none_or(|x| x == scheme) {
                return Err(provider_private::older_tool(what, &account));
            }
            Some(o)
        } else {
            None
        };
        if pinned.is_none() {
            if let Some(dir) = &wallet_dir {
                provider_private::write_pin(dir, &account, &scheme)?;
            }
        }
        let store = self.store();
        if !unknown && store.private.secrets.values().filter_map(Value::as_array).flatten().any(|g| g["account"] == account.as_str() && !g["scheme"].is_string()) {
            store.private.pin_scheme(&account, &scheme);
            store.save();
        }
        let imported = scheme == app_secret::SCHEME_IMPORTED;
        let mut reply = json!({ "granted": true, "account": account, "scope": ask.scope, "tag": ask.tag, "first": ask.first, "values": values, "imported": imported });
        if let Some(other) = other {
            reply["other_values"] = json!(other);
            reply["other_imported"] = json!(!imported);
        }
        Ok(reply)
    }

    /// Whether `account` is imported: the names CLI's word (`module account-scheme`, by key-tree
    /// membership), else the wallet file's list (`backup::accounts_of`, which reads no key and
    /// can't name an imported PRIVATE account); `None` when neither can tell.
    fn account_imported(&self, account: &str) -> Option<bool> {
        if let Ok(setup) = self.cli_setup() {
            if setup.wallet_ready().is_ok() {
                let input = json!({ "account": account });
                if let Ok(out) = cli::run_with_input(&setup, vec!["module".into(), "account-scheme".into()], &input.to_string(), SCHEME_PATIENCE) {
                    if let Ok(answer) = serde_json::from_str::<Value>(cli::last_line(&out)) {
                        if answer["account"] == account {
                            match answer["scheme"].as_str() {
                                Some(app_secret::SCHEME_IMPORTED) => return Some(true),
                                Some(app_secret::SCHEME_PHRASE) => return Some(false),
                                _ => {}
                            }
                        }
                    }
                }
            }
        }
        let dir = self.wallet_dir_of(self.net)?;
        let store = std::fs::read(dir.join(cli::STORAGE_FILE)).ok()?;
        let listed = backup::accounts_of(&store);
        let entries: Vec<&Value> = listed.iter().filter(|a| a["account"] == account).collect();
        if entries.is_empty() {
            // An imported PRIVATE account is listed without its id: a private account the file
            // doesn't name, in a wallet holding one, is taken as imported (it fails safe).
            let unnamed_private = listed.iter().any(|a| a["kind"] == "private" && a["imported"] == true && a["account"].is_null());
            return (account.starts_with("Private/") && unnamed_private).then_some(true);
        }
        // Listed in a key tree as well: a phrase account (the CLI's rule).
        Some(entries.iter().all(|a| a["imported"] == true))
    }

    /// Runs the CLI's simulation of a private call on its own thread; the request learns the
    /// outcome on its next refresh.
    fn start_private_check(&self, id: &str, input: Value) {
        let setup = self.cli_setup().and_then(|setup| setup.wallet_ready().map(|()| setup));
        let checks = std::sync::Arc::clone(&self.private_checks);
        let id = id.to_owned();
        let setup = match setup {
            Ok(setup) => setup,
            Err(why) => {
                // Said in words, never the busy envelope (the CLI's version still being read).
                let why = if is_busy(&why) { STILL_STARTING.to_owned() } else { why };
                checks.lock().expect("the private checks lock").insert(id, Err(why));
                return;
            }
        };
        std::thread::spawn(move || {
            let command = vec!["module".to_owned(), "private-call".to_owned(), "plan".to_owned()];
            let result = cli::run_with_input(&setup, command, &input.to_string(), PRIVATE_PLAN_PATIENCE)
                .and_then(|output| provider_private::report_of(&output).ok_or_else(|| cli::failure_cause(&output)));
            checks.lock().expect("the private checks lock").insert(id, result);
        });
    }

    /// Moves finished simulations into their requests, and follows running private calls'
    /// phases. Returns whether anything changed.
    fn private_refresh(&mut self) -> bool {
        let done: Vec<(String, Result<Value, String>)> = self.private_checks.lock().expect("the private checks lock").drain().collect();
        let jobs = self.jobs().ok();
        let store = self.store();
        let mut changed = false;
        for (id, result) in done {
            let Some(request) = store.get_mut(&id) else { continue };
            match result {
                Ok(report) => {
                    request["report"] = report;
                    request["check"] = json!("ready");
                }
                Err(why) => {
                    request["check"] = json!("failed");
                    request["check_problem"] = json!(crate::text::clean_remote(&why, 400));
                }
            }
            changed = true;
        }
        for request in store.requests.iter_mut().filter(|r| r["kind"] == provider::PRIVATE_CALL && r["state"] == "running") {
            let Some(job) = request["job"].as_str() else { continue };
            if let Some(jobs) = &jobs {
                let log = jobs.whole_log(job);
                let phase = provider_private::phase_of(&log).map(str::to_owned);
                if phase.is_some() && request["phase"].as_str() != phase.as_deref() {
                    request["phase"] = json!(phase);
                    changed = true;
                }
                if let Some(tx) = log.lines().find_map(|line| line.trim().strip_prefix("submitted ")) {
                    if request["tx"].as_str() != Some(tx.trim()) {
                        request["tx"] = json!(tx.trim());
                        changed = true;
                    }
                }
            }
        }
        changed
    }

    /// Approves a private call, a secret grant or a token source. `account` must be the one
    /// the request names.
    fn approve_private(&mut self, id: &str, request: &Value, account: &str) -> Result<Value, String> {
        let now = provider::now_ms();
        let kind = request["kind"].as_str().unwrap_or_default().to_owned();
        let app = request["app"].as_str().unwrap_or_default().to_owned();
        if kind != provider::TOKEN_SOURCE {
            let (private, chosen) = provider::account_ref(account)?;
            if request["account"] != provider::account_written(private, &chosen).as_str() {
                return Err("approve it with the account it names".to_owned());
            }
        }
        let mut outcome = json!({ "decided": now });
        match kind.as_str() {
            provider::SECRET => {
                let scope = request["scope"].as_str().unwrap_or_default().to_owned();
                let account = request["account"].as_str().unwrap_or_default().to_owned();
                // An exit's Ethereum address, approved on this sheet: kept for (app, account).
                if let Some(recipient) = request["exit"]["recipient"].as_str() {
                    let dir = self.wallet_dir_of(self.net).ok_or("there is no wallet folder to keep the approved address in; nothing was approved")?;
                    exit_recipient::approve(&dir, &app, &account, recipient)?;
                }
                self.store().private.grant_secret(&app, &account, &scope, now)?;
                outcome["state"] = json!("approved");
            }
            provider::TOKEN_SOURCE => {
                // The same rule as when it was asked, for one stored by an earlier build.
                self.token_source_allowed(request["token_program"].as_str().unwrap_or_default())?;
                self.store().private.add_token_source(request, now)?;
                self.forget_tokens();
                outcome["state"] = json!("approved");
            }
            provider::PRIVATE_CALL => {
                self.asked_here(request)?;
                if request["check"] != "ready" {
                    return Err("the wallet hasn't finished checking this call; wait for its summary".to_owned());
                }
                let sheet = self.private_sheet(request);
                if sheet["refused"] == true {
                    return Err("the wallet refuses this call (see why on the sheet); reject it".to_owned());
                }
                let digest = sheet["digest"].as_str().ok_or("the simulation gave no digest")?.to_owned();
                let job = self.private_call_job(request, &digest)?;
                let programs: Vec<String> = request["programs"].as_array().map(Vec::as_slice).unwrap_or_default().iter().filter_map(|p| p.as_str().map(str::to_owned)).collect();
                self.store().private.remember_programs(&app, &programs);
                outcome["state"] = json!("running");
                outcome["phase"] = json!("plan");
                outcome["job"] = job["id"].clone();
                outcome["approved_digest"] = json!(digest);
            }
            _ => return Err("this request can't be approved".to_owned()),
        }
        let store = self.store();
        let view = match store.get_mut(id) {
            Some(stored) => {
                for (key, value) in outcome.as_object().into_iter().flatten() {
                    stored[key.as_str()] = value.clone();
                }
                merged(provider::app_view(stored), &json!({ "job": stored["job"] }))
            }
            None => outcome,
        };
        store.save();
        Ok(view)
    }

    /// Approves a program declaration, or signs an approved relayed call and keeps the
    /// half-signed transaction for the app. Signing reads the nonces again: a call whose
    /// account or payer was used since builds to another hash, and is refused.
    fn approve_public(&mut self, id: &str, request: &Value, account: &str) -> Result<Value, String> {
        let now = provider::now_ms();
        let app = request["app"].as_str().unwrap_or_default().to_owned();
        let mut outcome = json!({ "decided": now });
        if request["kind"] == provider_public::PROGRAMS {
            let programs: Vec<String> = request["programs"].as_array().map(Vec::as_slice).unwrap_or_default().iter().filter_map(|p| p.as_str().map(str::to_owned)).collect();
            // The same rule as when it was asked: a declaration stored by an earlier build, or
            // asked before the configuration changed, never adds one of the wallet's own programs.
            let own = self.own_programs();
            if let Some((program, _)) = own.iter().find(|(known, _)| programs.contains(known)) {
                return Err(format!("{program} is one of the wallet's own programs (its Names registry or token program); the wallet doesn't let an app ask to sign calls to it. Reject this."));
            }
            self.store().private.declare(&app, &programs)?;
            outcome["state"] = json!("approved");
        } else {
            let (private, chosen) = provider::account_ref(account)?;
            if private || request["account"] != provider::account_written(false, &chosen).as_str() {
                return Err("approve it with the account it names".to_owned());
            }
            self.asked_here(request)?;
            if self.net != Net::Lez04 {
                return Err("switch to LEZ 0.4 to approve it".to_owned());
            }
            let program = request["program"].as_str().unwrap_or_default().to_owned();
            if !self.store().private.declared_of(&app).contains(&program) {
                return Err("this app no longer has that program declared; reject it".to_owned());
            }
            let sheet = self.relayed_sheet(request, true);
            if sheet["wait"] == true {
                // A bridge's Config still being read, or unreadable just now: the request stays
                // pending and nothing was signed; the person presses Approve again.
                let why = sheet["why"].as_array().and_then(|why| why.last()).and_then(Value::as_str).unwrap_or(STILL_READING);
                return Err(why.to_owned());
            }
            if sheet["refused"] == true {
                return Err("the wallet refuses this call (see why on the sheet); reject it".to_owned());
            }
            let hash = sheet["hash"].as_str().ok_or("the build gave no hash")?.to_owned();
            // What goes to the CLI to sign must be the bytes the sheet was made from: the
            // message is hashed again here, and the CLI refuses unless its own build of the
            // whole transaction has the hash shown.
            let message = registry::unhex(request["message"].as_str().unwrap_or_default()).unwrap_or_default();
            if registry::hex(&<sha2::Sha256 as sha2::Digest>::digest(&message)) != request["report"]["message_sha256"].as_str().unwrap_or_default() {
                return Err("the call to sign isn't the one shown; nothing was signed. Reject it.".to_owned());
            }
            let transaction = self.sign_relayed(id, request, &hash)?;
            outcome["state"] = json!("done");
            outcome["account"] = request["account"].clone();
            outcome["hash"] = json!(hash);
            outcome["transaction"] = json!(transaction);
            // What the person approved, kept as the yardstick of any re-sign (`resign_relayed_call`).
            outcome["approved_report"] = request["report"].clone();
            outcome["signed_payer_nonce"] = provider_public::payer_nonce(&request["report"]).map_or(Value::Null, |n| json!(n.to_string()));
            outcome["resigns"] = json!(0);
        }
        let store = self.store();
        let view = match store.get_mut(id) {
            Some(stored) => {
                for (key, value) in outcome.as_object().into_iter().flatten() {
                    stored[key.as_str()] = value.clone();
                }
                // The message was kept only to be signed (a relayed call's, for a bounded re-sign).
                if stored["kind"] != provider_public::RELAYED_CALL {
                    if let Some(fields) = stored.as_object_mut() {
                        fields.remove("message");
                    }
                }
                provider::app_view(stored)
            }
            None => outcome,
        };
        store.save();
        Ok(view)
    }

    /// Has the names CLI sign a relayed call as `hash` says (`module public-call sign`): it
    /// rebuilds the transaction from the chain's nonces and signs only if the hash is that one.
    /// The half-signed transaction, hex.
    fn sign_relayed(&self, id: &str, request: &Value, hash: &str) -> Result<String, String> {
        let setup = self.cli_setup()?;
        setup.wallet_ready()?;
        let jobs = self.jobs()?;
        let file = jobs.dir.join(format!("relayed-{id}.json"));
        std::fs::create_dir_all(&jobs.dir).map_err(|error| format!("cannot keep the call: {error}"))?;
        cli::write_private(&file, provider_public::cli_input(request, Some(hash)).to_string().as_bytes()).map_err(|error| format!("cannot keep the call: {error}"))?;
        let signed = cli::run_capture_text(&setup, vec!["module".into(), "public-call".into(), "sign".into(), format!("--input={}", file.display())], PUBLIC_PLAN_PATIENCE);
        let _ = std::fs::remove_file(&file);
        let signed: Value = serde_json::from_str(cli::last_line(&signed?)).map_err(|_| "the names CLI gave no signed call".to_owned())?;
        match signed["transaction"].as_str() {
            Some(transaction) if signed["hash"] == hash => Ok(transaction.to_owned()),
            _ => Err("the signed call isn't the one approved; nothing is given to the app".to_owned()),
        }
    }

    /// `resign_relayed_call`: signs an approved relayed call again when its payer's nonce has
    /// moved and nothing else has (`provider_public::resign_check`), within the window and the
    /// count the approval allows. Anything else needs the person's approval again.
    fn resign(&mut self, id: &str) -> Result<Value, (String, &'static str)> {
        // `refused`: not this app's, not signable here; `ask_again`: propose it again;
        // `unchanged`: send the transaction already given.
        let refused = |why: String| (why, "refused");
        let again = |why: String| (why, "ask_again");
        let app = asking_app().map_err(refused)?;
        let now = provider::now_ms();
        let request = self.store().get(id).filter(|r| r["app"] == app.as_str()).cloned().ok_or_else(|| refused("there is no such request".to_owned()))?;
        if request["kind"] != provider_public::RELAYED_CALL || request["state"] != "done" || !request["approved_report"].is_object() {
            return Err(refused("only a relayed call the person approved and the wallet signed can be signed again".to_owned()));
        }
        let decided = request["decided"].as_u64().unwrap_or(0);
        if now.saturating_sub(decided) > provider_public::RESIGN_WINDOW_MS {
            return Err(again(provider_public::ASK_AGAIN.replace("{why}", "the approval is more than 10 minutes old")));
        }
        if request["resigns"].as_u64().unwrap_or(0) >= provider_public::MAX_RESIGNS {
            return Err(again(provider_public::ASK_AGAIN.replace("{why}", "it was signed again 3 times already")));
        }
        // The signature binds no chain (rc3): after a reset of the bridge test network seen since
        // the call was asked, a new build is on a chain the person never saw it on.
        let reset_at = config_dir().and_then(|dir| bridge_net::reset_seen(&dir, now / 1000));
        if let Some(why) = provider_public::reset_refusal(reset_at, request["created"].as_u64().unwrap_or(decided)) {
            return Err(again(provider_public::ASK_AGAIN.replace("{why}", &why)));
        }
        self.asked_here(&request).map_err(again)?;
        if self.net != Net::Lez04 {
            return Err(refused("the wallet is on LEZ 0.3 now; it signs relayed calls on LEZ 0.4 only".to_owned()));
        }
        let program = request["program"].as_str().unwrap_or_default().to_owned();
        if !self.store().private.declared_of(&app).contains(&program) {
            return Err(again("this app no longer has that program declared".to_owned()));
        }
        // The rule about the wallet's own programs and the person's tokens, applied again; a burn
        // to a bridge is checked again against the bridge's Config read now.
        let own = self.own_programs();
        let (root_only, burn) = self.relayed_checks(&request, Check::Signing).map_err(refused)?;
        provider_public::programs_allowed(&request, &own, &Self::root_only_for(root_only, burn.as_ref())).map_err(refused)?;
        // The kept bytes are still the approved ones.
        let message = registry::unhex(request["message"].as_str().unwrap_or_default()).unwrap_or_default();
        if registry::hex(&<sha2::Sha256 as sha2::Digest>::digest(&message)) != request["approved_report"]["message_sha256"].as_str().unwrap_or_default() {
            return Err(again("the call to sign isn't the one approved; nothing was signed".to_owned()));
        }
        // The wallet builds it again (nonces from the chain) and compares the build with what
        // the person approved, field by field: only the payer's nonce may have moved.
        let setup = self.cli_setup().map_err(refused)?;
        setup.wallet_ready().map_err(refused)?;
        let output = cli::run_with_input(&setup, vec!["module".into(), "public-call".into(), "plan".into()], &provider_public::cli_input(&request, None).to_string(), PUBLIC_PLAN_PATIENCE)
            .map_err(|error| refused(format!("the wallet couldn't build this call again: {error}")))?;
        let report: Value = serde_json::from_str(cli::last_line(&output)).map_err(|_| refused("the names CLI gave no build the wallet can read".to_owned()))?;
        let last_payer_nonce = request["signed_payer_nonce"].as_str().and_then(|n| n.parse::<u128>().ok());
        if let Some(burn) = &burn {
            if let Some(first) = provider_public::burn_report_problems(&report, &request, burn).first() {
                return Err(refused(first.clone()));
            }
        }
        let hash = provider_public::resign_check(&request["approved_report"], last_payer_nonce, &report).map_err(|refusal| (refusal.text().to_owned(), refusal.code()))?;
        let transaction = self.sign_relayed(id, &request, &hash).map_err(refused)?;
        let store = self.store();
        let stored = store.get_mut(id).ok_or_else(|| refused("there is no such request".to_owned()))?;
        stored["transaction"] = json!(transaction);
        stored["hash"] = json!(hash);
        stored["resigns"] = json!(stored["resigns"].as_u64().unwrap_or(0) + 1);
        stored["signed_payer_nonce"] = provider_public::payer_nonce(&report).map_or(Value::Null, |n| json!(n.to_string()));
        stored["resigned"] = json!(now);
        let view = provider::app_view(stored);
        let line = json!({
            "kind": "resign", "chain": "lez", "app": app, "from": stored["account"], "program": stored["program"],
            "payer_nonce": stored["signed_payer_nonce"], "resigns": stored["resigns"], "state": "done",
        });
        store.save();
        // The person sees in the History each time the wallet signed again without asking.
        if let Some(dir) = config_dir() {
            activity::add(&dir, now, activity::in_zone(line, &self.zones.current_id()));
        }
        Ok(view)
    }

    /// The wallet's own programs, never reached by a relayed call: the Names registry of both
    /// networks (built-in and configured) and the token program its token methods use.
    fn own_programs(&self) -> Vec<(String, &'static str)> {
        let mut own: Vec<(String, &'static str)> = Vec::new();
        // Compared as canonical IDs: a stored `Public/<id>` or one with spaces is the same program.
        let mut add = |id: Option<String>, kind: &'static str| {
            if let Some(id) = id.and_then(|id| registry::parse_account(&id).ok()).map(|id| registry::account_text(&id)) {
                if !own.iter().any(|(known, _)| *known == id) {
                    own.push((id, kind));
                }
            }
        };
        add(Some(DEFAULT_REGISTRY.to_owned()), "names_registry");
        add(Some(LEZ04_REGISTRY.to_owned()), "names_registry");
        for retired in RETIRED_REGISTRIES {
            add(Some(retired.to_owned()), "names_registry");
        }
        add(self.program.as_ref().map(registry::account_text), "names_registry");
        add(self.parked["registry"].as_str().map(str::to_owned), "names_registry");
        // The wallet's own token program, except when it is a bridge's: a bridge claim declares
        // that one as an actor's program, and it is refused as root (`root_only`) instead.
        // What is known without a read (built in and kept): every check reads the bridges once,
        // in `root_only`, and keeps what it read, so a sheet costs one read per bridge.
        // A kept list that can't be read leaves the built-in ones; `root_only` refuses the call.
        let bridged = self.bridge_tokens_kept().unwrap_or_else(|_| bridge_net::KNOWN_TOKEN_PROGRAMS.iter().map(|id| (*id).to_owned()).collect());
        for token_program in [self.token_program.as_ref().map(registry::account_text), self.parked["token_program"].as_str().map(str::to_owned)] {
            let canonical = token_program.as_deref().and_then(|id| registry::parse_account(id).ok()).map(|id| registry::account_text(&id));
            if !canonical.is_some_and(|id| bridged.contains(&id)) {
                add(token_program, "token_program");
            }
        }
        own
    }

    /// A program call (`propose_call`) may not have a token program as its root (deep review A1):
    /// the holder's tokens sit in its own actor of that program, so a root call it signs can move
    /// them, which the call's sheet doesn't say. The wallet's token programs, every bridge's (as
    /// known now, never waited for) and the token sources' are refused; tokens are sent with
    /// `propose_transfer`. Checked when asked and again at approval.
    fn call_root_allowed(&mut self, program: &AccountId) -> Result<(), String> {
        let text = registry::account_text(program);
        let own_tokens = self.own_programs().into_iter().any(|(id, kind)| kind == "token_program" && id == text);
        if own_tokens || self.root_only_lenient(Check::Signing).iter().any(|(id, _)| *id == text) {
            return Err(format!("{text} is a token program; a program call can't have it as its root, since it could move the tokens the account holds. Send tokens with propose_transfer"));
        }
        Ok(())
    }

    /// Whether `program` is one of the NFT programs in the person's list for this network.
    fn is_listed_nft_program(&self, program: &AccountId) -> bool {
        let text = registry::account_text(program);
        self.nft_list().unwrap_or_default().iter().any(|entry| entry["program"].as_str().and_then(|p| registry::parse_account(p).ok()).is_some_and(|p| registry::account_text(&p) == text))
    }

    /// A token source may not name a bridge program or one of the wallet's own programs (SF-4):
    /// once approved, its program is refused as a relayed call's root, which would refuse every
    /// claim to that bridge.
    fn token_source_allowed(&self, program: &str) -> Result<(), String> {
        let id = registry::parse_account(program.trim().strip_prefix("Public/").unwrap_or(program.trim()))?;
        if self.bridge_programs_now().contains(&id) {
            return Err(format!("{} is a bridge program, not a token program; the wallet doesn't take it as a token source", registry::account_text(&id)));
        }
        let text = registry::account_text(&id);
        if let Some((_, kind)) = self.own_programs().iter().find(|(known, _)| *known == text) {
            return Err(format!("{text} is one of the wallet's own programs ({}); the wallet doesn't take it as a token source", kind.replace('_', " ")));
        }
        Ok(())
    }

    /// Programs a relayed call may never have as its root (`provider_public::RootOnly`): the
    /// token programs of the bridges on LEZ 0.4, where the person's bridged tokens sit (built in,
    /// every one read before, and every configured bridge's from its Config), the wallet's token
    /// programs, and the token programs of the token sources apps added. If one bridge's token
    /// program can't be read, nothing is signed: the error is returned and the caller refuses
    /// (fail closed); while one is still being read, `STILL_READING`.
    ///
    /// `check` says where the Configs come from, never from a read on this thread (`Check`).
    fn root_only_now(&mut self, check: Check) -> Result<Vec<(String, &'static str)>, String> {
        let mut read_now: Vec<String> = Vec::new();
        for (program, read) in self.bridge_tokens_now(check)? {
            match read {
                Known::Read(Some(token_program)) => read_now.push(registry::account_text(&token_program)),
                Known::Read(None) => {}
                Known::Unread(why) => {
                    return Err(format!("the wallet couldn't check the token program of bridge {} ({why}) just now, so it signs nothing; try again", registry::account_text(&program)));
                }
                Known::Reading => return Err(STILL_READING.to_owned()),
            }
        }
        let bridged = self.bridge_tokens_with(read_now).map_err(|why| format!("the wallet couldn't check {why} just now, so it signs nothing; try again"))?;
        Ok(self.root_only_from(bridged))
    }

    /// `root_only` for a call checked as a burn to a bridge: what is known now (built in, kept, and
    /// each bridge's token program as read), never waited for. A bridge whose Config can't be read
    /// adds nothing here: the burn's root is its target's token program, checked exactly against
    /// that bridge's own Config (`burn_gate_now`); no other bridge's read bears on it.
    fn root_only_lenient(&mut self, check: Check) -> Vec<(String, &'static str)> {
        let read_now: Vec<String> = match check {
            Check::Sheet => self.bridge_tokens_now(Check::Sheet).unwrap_or_default(),
            Check::Signing => self.tokens_within(bridge_net::CONFIG_FRESH, std::time::Duration::ZERO),
        }
        .into_iter()
        .filter_map(|(_, read)| match read {
            Known::Read(Some(token_program)) => Some(registry::account_text(&token_program)),
            _ => None,
        })
        .collect();
        let bridged = self.bridge_tokens_with(read_now).unwrap_or_else(|_| bridge_net::KNOWN_TOKEN_PROGRAMS.iter().map(|id| (*id).to_owned()).collect());
        self.root_only_from(bridged)
    }

    /// `root_only` from the bridge token programs `bridged`.
    fn root_only_from(&mut self, bridged: Vec<String>) -> Vec<(String, &'static str)> {
        let mut list: Vec<(String, &'static str)> = Vec::new();
        let sources = self.known_token_programs();
        for id in bridged
            .into_iter()
            .map(Some)
            .chain([self.token_program.as_ref().map(registry::account_text), self.parked["token_program"].as_str().map(str::to_owned)])
            .chain(sources.into_iter().map(Some))
            .flatten()
            .filter_map(|id| registry::parse_account(&id).ok().map(|id| registry::account_text(&id)))
        {
            if !list.iter().any(|(known, _)| *known == id) {
                list.push((id, "bridged_tokens"));
            }
        }
        list
    }

    /// Where the bridges' Configs are read: LEZ 0.4's endpoint (a test or a trial of a new chain may
    /// point elsewhere for one run).
    fn bridge_url(&self) -> String {
        std::env::var("LOGOS_NAMES_BRIDGE_RPC").ok().filter(|url| !url.trim().is_empty()).unwrap_or_else(|| self.lez04_rpc())
    }

    /// Each configured bridge's token program as the check takes it: a sheet's from the last
    /// background read (`SheetReads`, `STILL_READING` before the first); a signing's from what was
    /// read within `CONFIG_FRESH`, else read on its own thread and waited for `FIRST_WAIT` at most.
    fn bridge_tokens_now(&self, check: Check) -> Result<Vec<(AccountId, Known<AccountId>)>, String> {
        match check {
            Check::Sheet => {
                let key = format!("{}|{:?}", self.bridge_url(), self.bridge_programs_now());
                match self.sheet_reads.tokens.get(&key, SHEET_READ_EVERY, self.tokens_reader(bridge_net::CONFIG_FRESH)) {
                    None => Err(STILL_READING.to_owned()),
                    Some(read) => read,
                }
            }
            Check::Signing => Ok(self.tokens_within(bridge_net::CONFIG_FRESH, served::FIRST_WAIT)),
        }
    }

    /// A bridge's token program as its Config bytes name it, for the configured `programs`: a
    /// Config naming a bridge program itself as its token program is unreadable (it would make every
    /// claim to that bridge refused for good once kept).
    fn token_known(_program: &AccountId, programs: &[AccountId], read: Result<Option<AccountId>, String>) -> Known<AccountId> {
        match read {
            Ok(Some(token_program)) if programs.contains(&token_program) => Known::Unread("its Config names a bridge program as its token program".to_owned()),
            Ok(found) => Known::Read(found),
            Err(why) => Known::Unread(why),
        }
    }

    /// Whether this test reads the bridges' Configs over HTTP from its stand-in endpoint
    /// (`tests::BRIDGE_HTTP`, the stall tests); any other test's unset bridge has no Config.
    #[cfg(test)]
    fn stand_in(_url: &str) -> bool {
        tests::BRIDGE_HTTP.with(std::cell::Cell::get)
    }

    /// The reads behind `bridge_tokens_now` for a sheet, as a job that owns what it needs: each
    /// configured bridge's token program from its Config read at most `max_age` ago (blocking: a
    /// background thread's, or a unit test's on the spot).
    fn tokens_reader(&self, max_age: std::time::Duration) -> impl FnOnce() -> Result<Vec<(AccountId, Known<AccountId>)>, String> + Send + 'static {
        let url = self.bridge_url();
        // Tests set what the chain would say for each bridge (`BRIDGE_CONFIGS`); unset, no Config,
        // except on a stand-in endpoint, which is read. Taken now, on the test's thread.
        #[cfg(test)]
        let said: HashMap<String, Result<Option<String>, String>> = tests::BRIDGE_CONFIGS.with(|configs| configs.borrow().clone());
        #[cfg(test)]
        let over_http = Self::stand_in(&url);
        let programs = self.bridge_programs_now();
        move || {
            // Each bridge on a thread of its own (a dead endpoint costs one wait, not six).
            let read = |program: &AccountId| -> Known<AccountId> {
                #[cfg(test)]
                {
                    if let Some(answer) = said.get(&registry::account_text(program)) {
                        let answer = answer.clone().and_then(|found| found.map(|id| registry::parse_account(&id)).transpose());
                        return Self::token_known(program, &programs, answer);
                    }
                    if !over_http {
                        return Known::Read(None);
                    }
                }
                Self::token_known(program, &programs, bridge_net::token_program_of(&url, program, max_age))
            };
            Ok(std::thread::scope(|scope| {
                let reads: Vec<_> = programs
                    .iter()
                    .map(|program| {
                        let read = &read;
                        scope.spawn(move || {
                            served::as_background();
                            (*program, read(program))
                        })
                    })
                    .collect();
                reads.into_iter().zip(&programs).map(|(reader, program)| reader.join().unwrap_or((*program, Known::Unread("a read failed".to_owned())))).collect()
            }))
        }
    }

    /// Each configured bridge's token program for a check made on a call's thread: what was read
    /// within `max_age`, else a read started on its own thread (all of them at once) and waited for
    /// `wait` at most in all.
    fn tokens_within(&self, max_age: std::time::Duration, wait: std::time::Duration) -> Vec<(AccountId, Known<AccountId>)> {
        let url = self.bridge_url();
        let programs = self.bridge_programs_now();
        #[cfg(test)]
        if self.served.inline || !Self::stand_in(&url) {
            return (self.tokens_reader(max_age))().unwrap_or_default();
        }
        for program in &programs {
            let _ = bridge_net::config_within(&url, program, max_age, std::time::Duration::ZERO);
        }
        let until = std::time::Instant::now() + wait;
        programs
            .iter()
            .map(|program| {
                let left = until.saturating_duration_since(std::time::Instant::now());
                let known = match bridge_net::config_within(&url, program, max_age, left) {
                    bridge_net::ConfigNow::Read(None) => Self::token_known(program, &programs, Ok(None)),
                    bridge_net::ConfigNow::Read(Some(bytes)) => Self::token_known(program, &programs, bridge_net::decode_config(&bytes).map(|(token_program, _)| Some(token_program))),
                    bridge_net::ConfigNow::Unread(why) => Known::Unread(why),
                    bridge_net::ConfigNow::Reading => Known::Reading,
                };
                (*program, known)
            })
            .collect()
    }

    /// The reads behind a burn's sheet, as a job that owns what it needs: the Config of each bridge a
    /// relayed burn may go to (`bridge_net::BURN_BRIDGES`), read at most `max_age` ago.
    fn burns_reader(&self, max_age: std::time::Duration) -> impl FnOnce() -> Result<Vec<(AccountId, Known<bridge_net::BridgeConfig>)>, String> + Send + 'static {
        let url = self.bridge_url();
        // Tests set the Config the chain would give (`BURN_CONFIGS`); unset, none, except on a
        // stand-in endpoint, which is read.
        #[cfg(test)]
        let said: HashMap<String, Result<Option<bridge_net::BridgeConfig>, String>> = tests::BURN_CONFIGS.with(|configs| configs.borrow().clone());
        #[cfg(test)]
        let over_http = Self::stand_in(&url);
        move || {
            let read = |text: &str, program: &AccountId| -> Known<bridge_net::BridgeConfig> {
                #[cfg(test)]
                {
                    if let Some(answer) = said.get(text) {
                        return answer.clone().map_or_else(Known::Unread, Known::Read);
                    }
                    if !over_http {
                        return Known::Read(None);
                    }
                }
                let _ = text;
                bridge_net::config_of(&url, program, max_age).map_or_else(Known::Unread, Known::Read)
            };
            let programs: Vec<(&str, AccountId)> = bridge_net::BURN_BRIDGES.iter().map(|text| registry::parse_account(text).map(|id| (*text, id))).collect::<Result<_, _>>()?;
            // Each bridge on a thread of its own, as for the token programs.
            Ok(std::thread::scope(|scope| {
                let reads: Vec<_> = programs
                    .iter()
                    .map(|(text, program)| {
                        let read = &read;
                        scope.spawn(move || {
                            served::as_background();
                            (*program, read(text, program))
                        })
                    })
                    .collect();
                reads.into_iter().zip(&programs).map(|(reader, (_, program))| reader.join().unwrap_or((*program, Known::Unread("a read failed".to_owned())))).collect()
            }))
        }
    }

    /// The Configs of the bridges a burn may go to, for a check made on a call's thread: the
    /// burn's `target` read within `BURN_SIGN_FRESH` (else read on its own thread and waited for
    /// `FIRST_WAIT` at most), the others as kept within `CONFIG_FRESH` (never waited for: they only
    /// word a refusal).
    fn burns_within(&self, target: Option<&AccountId>) -> Vec<(AccountId, Known<bridge_net::BridgeConfig>)> {
        let url = self.bridge_url();
        #[cfg(test)]
        if self.served.inline || !Self::stand_in(&url) {
            return (self.burns_reader(bridge_net::BURN_SIGN_FRESH))().unwrap_or_default();
        }
        bridge_net::BURN_BRIDGES
            .iter()
            .filter_map(|text| registry::parse_account(text).ok())
            .map(|program| {
                let (max_age, wait) = if Some(&program) == target { (bridge_net::BURN_SIGN_FRESH, served::FIRST_WAIT) } else { (bridge_net::CONFIG_FRESH, std::time::Duration::ZERO) };
                let known = match bridge_net::config_within(&url, &program, max_age, wait) {
                    bridge_net::ConfigNow::Read(None) => Known::Read(None),
                    bridge_net::ConfigNow::Read(Some(bytes)) => bridge_net::decode_bridge_config(&bytes).map_or_else(Known::Unread, |config| Known::Read(Some(config))),
                    bridge_net::ConfigNow::Unread(why) => Known::Unread(why),
                    bridge_net::ConfigNow::Reading => Known::Reading,
                };
                (program, known)
            })
            .collect()
    }

    /// The bridge a burn tells what was burned (its message's notify program), when it is one a
    /// relayed burn may go to.
    fn burn_target(request: &Value) -> Option<AccountId> {
        let message = registry::unhex(request["message"].as_str().unwrap_or_default()).ok()?;
        let notified = bridge_net::decode_burn(&message).ok()?.notify_program;
        bridge_net::BURN_BRIDGES.iter().any(|text| registry::parse_account(text).ok() == Some(notified)).then_some(notified)
    }

    /// A relayed call that says it is a burn to a bridge (privacy `bridge_public_burn`), checked
    /// exactly (`provider_public::burn_check`) against the Config of the bridge it notifies; `None`
    /// for any other call. Recomputed from the stored bytes at every step (sheet, approval, re-sign,
    /// proposal), never kept. `check`: a sheet's Configs come from the background read (the target's
    /// at most `BURN_SHEET_FRESH` old), a signing's from `burns_within` (`BURN_SIGN_FRESH`).
    fn burn_gate_now(&self, request: &Value, check: Check) -> Result<Option<provider_public::BridgeBurn>, String> {
        if request["privacy"] != provider_public::BURN_PRIVACY {
            return Ok(None);
        }
        let reads = match check {
            Check::Sheet => match self.sheet_reads.burns.get(&self.bridge_url(), SHEET_READ_EVERY, self.burns_reader(bridge_net::BURN_SHEET_FRESH)) {
                None => return Err(STILL_READING.to_owned()),
                Some(reads) => reads?,
            },
            Check::Signing => self.burns_within(Self::burn_target(request).as_ref()),
        };
        Self::burn_gate_per_bridge(request, &reads)
    }

    /// `burn_gate_with` from each burn bridge's read: the Config of the bridge the burn notifies must
    /// be read (an unreadable one, or one still being read, is a plain wait: nothing signed, try
    /// again); every other bridge's read bears on nothing but the words of a refusal, so a bridge
    /// whose Config can't be read never refuses a burn toward another.
    fn burn_gate_per_bridge(request: &Value, reads: &[(AccountId, Known<bridge_net::BridgeConfig>)]) -> Result<Option<provider_public::BridgeBurn>, String> {
        if request["privacy"] != provider_public::BURN_PRIVACY {
            return Ok(None);
        }
        Self::burn_target_read(request, reads)?;
        let configs: Vec<(AccountId, bridge_net::BridgeConfig)> = reads
            .iter()
            .filter_map(|(program, read)| match read {
                Known::Read(Some(config)) => Some((*program, config.clone())),
                _ => None,
            })
            .collect();
        Self::burn_gate_with(request, &configs)
    }

    /// A plain wait when the Config of the bridge a burn notifies couldn't be read just now or is
    /// still being read; Ok otherwise (read, or not a bridge a burn may go to).
    fn burn_target_read(request: &Value, reads: &[(AccountId, Known<bridge_net::BridgeConfig>)]) -> Result<(), String> {
        if let Some(target) = Self::burn_target(request) {
            let text = registry::account_text(&target);
            let label = bridge_net::bridge_label(&text).map_or_else(|| text.clone(), str::to_owned);
            match reads.iter().find(|(program, _)| *program == target).map(|(_, read)| read) {
                Some(Known::Unread(why)) => {
                    return Err(format!("the wallet couldn't read the Config of {label} just now ({why}), so it signs no burn to it; try again in a moment. Nothing was signed."));
                }
                Some(Known::Reading) => {
                    return Err(format!("the wallet is still reading the Config of {label} on LEZ 0.4 to check this burn; try again in a moment. Nothing was signed."));
                }
                _ => {}
            }
        }
        Ok(())
    }

    fn burn_gate_with(request: &Value, configs: &[(AccountId, bridge_net::BridgeConfig)]) -> Result<Option<provider_public::BridgeBurn>, String> {
        if request["privacy"] != provider_public::BURN_PRIVACY {
            return Ok(None);
        }
        let program = request["program"].as_str().unwrap_or_default();
        // Bridges can share a token program (v4 and v5 do): the burn is checked against the one
        // allowed bridge it notifies, never just the first with that token program.
        let same_tokens: Vec<&(AccountId, bridge_net::BridgeConfig)> =
            configs.iter().filter(|(_, config)| registry::account_text(&config.token_program) == program).collect();
        let first = *same_tokens.first().ok_or(NOT_A_BURN_BRIDGE)?;
        let notified = registry::unhex(request["message"].as_str().unwrap_or_default())
            .ok()
            .and_then(|message| bridge_net::decode_burn(&message).ok())
            .map(|burn| burn.notify_program);
        let (bridge, config) = same_tokens.into_iter().find(|(bridge, _)| notified.as_ref() == Some(bridge)).unwrap_or(first);
        provider_public::burn_check(request, bridge, config).map(Some)
    }

    /// `root_only` without the token program of a checked burn (that one root is allowed).
    fn root_only_for(root_only: Vec<(String, &'static str)>, burn: Option<&provider_public::BridgeBurn>) -> Vec<(String, &'static str)> {
        match burn {
            Some(burn) => root_only.into_iter().filter(|(id, _)| *id != burn.token_program).collect(),
            None => root_only,
        }
    }

    /// What a relayed call is checked against, by its kind: a burn by its target bridge's Config and
    /// what is known of the rest (`root_only_lenient`); any other call by every bridge's token
    /// program (`root_only_now`, fail closed).
    fn relayed_checks(&mut self, request: &Value, check: Check) -> Result<(Vec<(String, &'static str)>, Option<provider_public::BridgeBurn>), String> {
        let burn = self.burn_gate_now(request, check)?;
        let root_only = if burn.is_some() { self.root_only_lenient(check) } else { self.root_only_now(check)? };
        Ok((root_only, burn))
    }

    /// Before the bridge list changes, the token program of each bridge listed now is read and
    /// kept (SF-2), so a bridge removed before any relayed call was checked stays refused as root.
    /// Best effort, and never on this thread: the reads (an hour's kept Configs, else the network)
    /// run on a thread of their own, which keeps what they give.
    fn keep_bridge_tokens_before_change(&self) {
        let reader = self.tokens_reader(bridge_net::CONFIG_FRESH);
        let keep = move || {
            let read: Vec<String> = reader()
                .unwrap_or_default()
                .into_iter()
                .filter_map(|(_, read)| match read {
                    Known::Read(Some(token_program)) => Some(registry::account_text(&token_program)),
                    _ => None,
                })
                .collect();
            if let Some(dir) = config_dir() {
                bridge_net::keep_token_programs(&dir, &read);
            }
        };
        if self.served.inline {
            keep();
        } else {
            served::spawn(keep);
        }
    }

    /// The bridge token programs known without a read: the built-in ones and every one read before
    /// (`bridge_net::KNOWN_TOKEN_PROGRAMS`, `SEEN_TOKEN_PROGRAMS`).
    fn bridge_tokens_kept(&self) -> Result<Vec<String>, String> {
        let mut out: Vec<String> = bridge_net::KNOWN_TOKEN_PROGRAMS.iter().map(|id| (*id).to_owned()).collect();
        let kept = match config_dir() {
            Some(dir) => bridge_net::seen_token_programs(&dir).map_err(|why| format!("the list of bridge token programs it keeps ({why}; deleting the file resets it)"))?,
            None => Vec::new(),
        };
        for id in kept {
            if !out.contains(&id) {
                out.push(id);
            }
        }
        Ok(out)
    }

    /// The bridge token programs on LEZ 0.4 from the reads `read_now`: kept for good (a sequencer
    /// that later answers "no Config" can't shrink the list), and added to the ones known without a
    /// read.
    fn bridge_tokens_with(&self, read_now: Vec<String>) -> Result<Vec<String>, String> {
        if let Some(dir) = config_dir() {
            bridge_net::keep_token_programs(&dir, &read_now);
        }
        let mut out = self.bridge_tokens_kept()?;
        for id in read_now {
            if !out.contains(&id) {
                out.push(id);
            }
        }
        Ok(out)
    }

    /// The approval sheet of a program declaration: each program's full ID and what the Program
    /// Registry says of it, with its warnings (an unregistered or unverified program needs the tick).
    fn programs_sheet(&self, request: &Value) -> Value {
        let mut programs = Vec::new();
        let mut warnings: Vec<Value> = Vec::new();
        for program in request["programs"].as_array().map(Vec::as_slice).unwrap_or_default() {
            let id = program.as_str().unwrap_or_default();
            let label = provider::label_fields(program_registry::label(id).as_ref());
            for warning in provider::label_warnings(&label, "program") {
                warnings.push(json!(format!("{}: {warning}", id)));
            }
            programs.push(json!({ "program": id, "label": label }));
        }
        json!({ "programs": programs, "warnings": warnings })
    }

    /// The approval sheet of a relayed call (`provider_public::sheet`), with the program's
    /// Program Registry label and the network as the site names it.
    /// `fresh`: the LEZ 0.4 reads are made now (approving). Otherwise (the sheet a poll shows)
    /// they come from the last background read and never wait: until the first one is back the
    /// sheet is refused, saying it is still reading (fail closed, as for a failed read).
    fn relayed_sheet(&mut self, request: &Value, fresh: bool) -> Value {
        let label = request["program"].as_str().and_then(program_registry::label);
        // The network the call was asked for, not the one in use now.
        let shown = request["network"].as_str().and_then(Net::parse).unwrap_or(self.net).shown();
        let network = format!("{} · {}", shown["version"].as_str().unwrap_or_default(), shown["name"].as_str().unwrap_or_default());
        let own = self.own_programs();
        let checked = self.relayed_checks(request, if fresh { Check::Signing } else { Check::Sheet });
        match checked {
            Ok((root_only, burn)) => {
                provider_public::sheet(request, &request["report"], label.as_ref(), &network, &own, &Self::root_only_for(root_only, burn.as_ref()), burn.as_ref())
            }
            Err(why) => {
                // Fail closed: shown, but refused, until the wallet can read which program holds
                // the person's bridged tokens (and, for a burn, the bridge's Config).
                let mut sheet = provider_public::sheet(request, &request["report"], label.as_ref(), &network, &own, &[], None);
                sheet["refused"] = json!(true);
                // A read still under way (or one to try again) is a wait, not a refusal of the call.
                sheet["wait"] = json!(is_wait(&why));
                if let Some(list) = sheet["why"].as_array_mut() {
                    list.push(json!(why));
                }
                sheet
            }
        }
    }

    /// The approval sheet of a private call (see `provider_private::review`), with the
    /// Program Registry's labels, the token sources' names and the programs this app used before.
    fn private_sheet(&mut self, request: &Value) -> Value {
        let mut labels = Map::new();
        for program in request["programs"].as_array().map(Vec::as_slice).unwrap_or_default() {
            if let Some(program) = program.as_str() {
                if let Some(label) = program_registry::label(program) {
                    labels.insert(program.to_owned(), label);
                }
            }
        }
        let app = request["app"].as_str().unwrap_or_default().to_owned();
        let store = self.store();
        let names = store.private.token_names();
        let remembered = store.private.programs_of(&app);
        provider_private::review(request, &request["report"], &labels, &names, &remembered)
    }

    /// Starts `names module private-call send` for an approved call: the CLI simulates it
    /// again, refuses unless what it does still matches `digest` (what the person saw), then
    /// proves and sends it. The call goes in a 0600 file the job removes when it ends.
    fn private_call_job(&mut self, request: &Value, digest: &str) -> Result<Value, String> {
        let setup = self.cli_setup()?;
        setup.wallet_ready()?;
        self.no_background_job()?;
        let jobs = self.jobs()?;
        let id = jobs.prepare(cli::WALLET_JOB)?;
        let file = jobs.scratch(&id, "call");
        let input = provider_private::cli_input(request, Some(digest), &self.known_token_programs());
        cli::write_private(&file, input.to_string().as_bytes()).map_err(|error| format!("cannot keep the call: {error}"))?;
        let command = vec!["module".to_owned(), "private-call".to_owned(), "send".to_owned(), format!("--input={}", file.display())];
        jobs.start(&setup, &id, cli::WALLET_JOB, "private_call", command, Some(file))
    }

    /// Pauses (SIGSTOP), resumes (SIGCONT) or cancels (SIGTERM, then SIGKILL) a private call's
    /// job, which runs in its own process group, while it hasn't started sending.
    fn control_private_call(&mut self, id: &str, action: &str) -> Result<Value, String> {
        self.provider_refresh();
        let request = self.store().get(id).cloned().ok_or("there is no such request")?;
        if request["kind"] != provider::PRIVATE_CALL || request["state"] != "running" {
            return Err("only a private call that is running can be paused or cancelled".to_owned());
        }
        if !provider_private::may_stop(request["phase"].as_str()) && action != "resume" {
            return Err("it is being sent; it can't be stopped now".to_owned());
        }
        let job = request["job"].as_str().ok_or("this call has no job")?.to_owned();
        let state = self.jobs()?.state(&job)?;
        let pid = state["pid"].as_u64().ok_or("the job's process is unknown")?;
        let group = format!("-{pid}");
        let signal = |name: &str| {
            std::process::Command::new("/bin/kill")
                .args([name, "--", &group])
                .status()
                .map_err(|error| format!("could not signal the job: {error}"))
                .and_then(|status| if status.success() { Ok(()) } else { Err("the job has ended".to_owned()) })
        };
        let now = provider::now_ms();
        let store = self.store();
        let stored = store.get_mut(id).ok_or("there is no such request")?;
        match action {
            "pause" => {
                signal("-STOP")?;
                stored["paused"] = json!(true);
            }
            "resume" => {
                signal("-CONT")?;
                stored["paused"] = json!(false);
            }
            "cancel" => {
                // A stopped group must run again to take the TERM.
                let _ = signal("-CONT");
                signal("-TERM")?;
                let group = group.clone();
                std::thread::spawn(move || {
                    std::thread::sleep(std::time::Duration::from_secs(5));
                    let _ = std::process::Command::new("/bin/kill").args(["-KILL", "--", &group]).status();
                });
                stored["state"] = json!("cancelled");
                stored["decided"] = json!(now);
                // `submit` is printed only once the wallet has proven and handed it over, so a
                // cancel late in proving may come after it went: never say nothing was sent.
                stored["error"] = json!("cancelled while it was being proven; if the proof had just finished it may still have been sent, so check the account before asking again");
            }
            _ => return Err("the action is pause, resume or cancel".to_owned()),
        }
        let view = provider::app_view(stored);
        store.save();
        Ok(view)
    }

    /// `token_source_holdings`.
    fn source_holdings(&mut self) -> Result<Value, String> {
        let sources = self.store().private.token_sources.clone();
        let names = self.store().private.token_names();
        let setup = self.cli_setup()?;
        setup.wallet_ready()?;
        let mut out = Vec::new();
        for source in sources {
            let Some(program) = source["token_program"].as_str().and_then(|text| registry::parse_account(text).ok()) else { continue };
            let reader = setup.clone();
            let key = format!("{TOKENS_KEY}{}:{}", registry::account_text(&program), setup.wallet.display());
            let read = self.read_in_background(key, TOKENS_EVERY, move || cli::run_token_list(&reader, &program));
            let holdings: Vec<Value> = read["value"]["holdings"]
                .as_array()
                .map(Vec::as_slice)
                .unwrap_or_default()
                .iter()
                .filter_map(|row| {
                    let definition = row["definition"].as_str()?;
                    let named = names.get(definition)?;
                    if named["token_program"] != registry::account_text(&program).as_str() {
                        return None;
                    }
                    Some(merged(row.clone(), &json!({ "name": named["name"], "symbol": named["symbol"], "decimals": named["decimals"], "origin": named["origin"], "chain_name": row["name"] })))
                })
                .collect();
            // `definitions`: the tokens this source lists, so the app can tell "holds none" (listed,
            // read) from "can't be read here" (not listed). `read`: a read has been made; until
            // then `holdings` is empty without meaning "holds none" (wallet-1120: a dropped read
            // made a burned private holding look unreadable, and every amount was offered).
            let definitions: Vec<Value> = source["definitions"]
                .as_array()
                .map(Vec::as_slice)
                .unwrap_or_default()
                .iter()
                .filter_map(|d| d["definition"].as_str().or_else(|| d.as_str()).map(Value::from))
                .collect();
            out.push(json!({ "token_program": source["token_program"], "app": source["app"], "definitions": definitions, "read": !read["value"].is_null(), "holdings": holdings, "updating": read["updating"], "error": read["error"] }));
        }
        Ok(Value::from(out))
    }
}

/// The prefix of the token reads' keys among the background reads.
const TOKENS_KEY: &str = "tokens:";
/// How often the token reads may run the CLI; each catches the wallet up.
const TOKENS_EVERY: std::time::Duration = std::time::Duration::from_secs(20);

/// The value of a reply this module made, or its error.
fn parsed_reply(text: &str) -> Result<Value, String> {
    let reply: Value = serde_json::from_str(text).map_err(|_| "an unreadable answer".to_owned())?;
    if reply["success"] == true {
        Ok(reply["value"].clone())
    } else {
        Err(reply["error"].as_str().unwrap_or("it failed").to_owned())
    }
}

/// The most names, and the most answers, the module keeps in memory at once.
const MAX_CACHED: usize = 512;

/// A wallet can hold many accounts and each costs a read, so `wallet` stops here.
const MAX_WALLET_ACCOUNTS: usize = 64;

/// The SHA-256 of the `.lgx` file at `path` (lowercase hex): `file_sha256`.
fn lgx_sha256(path: &str) -> Result<String, String> {
    use sha2::{Digest, Sha256};
    let path = std::path::Path::new(path);
    if !path.is_absolute() || path.extension().and_then(|e| e.to_str()) != Some("lgx") {
        return Err("only a package file (.lgx) given by its full path".to_owned());
    }
    let meta = std::fs::metadata(path).map_err(|_| "that package file isn't there".to_owned())?;
    if !meta.is_file() || meta.len() > 64 << 20 {
        return Err("that isn't a package file of at most 64 MiB".to_owned());
    }
    let bytes = std::fs::read(path).map_err(|e| format!("couldn't read that package file: {e}"))?;
    Ok(Sha256::digest(&bytes).iter().map(|b| format!("{b:02x}")).collect())
}

/// Whether package_manager's list of installed packages (`answer`, as the host hands it: the
/// list, JSON text of it, or `{success, value}` around either) names `name`. None unless the list
/// was read for sure: it must hold this names module itself, so an answer of another shape is
/// never taken for "not installed".
fn package_listed(answer: &Value, name: &str) -> Option<bool> {
    let mut value = answer.clone();
    for _ in 0..4 {
        value = match value {
            Value::String(text) => serde_json::from_str(&text).ok()?,
            Value::Object(ref map) if map.contains_key("value") => map["value"].clone(),
            other => return value_list(other, name),
        };
    }
    None
}

fn value_list(value: Value, name: &str) -> Option<bool> {
    let list = value.as_array()?;
    let named = |wanted: &str| list.iter().any(|entry| entry["name"].as_str() == Some(wanted));
    named("names").then(|| named(name))
}

/// The Program Registry module (`program_registry`, LP-0023), asked what a
/// program is and whether its source is verified, for a program call's
/// prompt. It is optional: without it the prompt says so.
/// What the Program Registry said about a program or an app, as far as is known now.
#[derive(Debug, Clone, PartialEq)]
pub(crate) enum Looked {
    /// Its answer.
    Known(Value),
    /// Asked, no answer yet: nothing that depends on it may be approved until it answers
    /// (it may be a warning). Lasts a few seconds.
    Checking,
    /// The registry isn't installed, didn't answer, or couldn't say (the sheet warns).
    Missing,
}

impl Looked {
    pub(crate) fn known(self) -> Option<Value> {
        match self {
            Looked::Known(value) => Some(value),
            _ => None,
        }
    }
}

#[cfg(not(test))]
mod program_registry {
    use super::{json, peer, Looked, Value};
    use std::collections::HashMap;
    use std::sync::atomic::{AtomicU64, Ordering};
    use std::sync::Mutex;
    use std::time::Duration;

    const MODULE: &str = "program_registry";

    /// How long one ask may wait for the module (the host may wait longer to learn it's absent).
    const LOOK: Duration = Duration::from_secs(3);
    /// How long an answer is kept: a sheet asks again on every poll, and must show (and approval
    /// must see) the same thing for its life.
    const KEEP_S: u64 = 30 * 60;
    /// How long a failed ask (no answer, or an error) is kept before asking again; and, per kind,
    /// how long the module counts as absent after an ask found it missing.
    const FAILED_S: u64 = 60;

    /// What was learned, by `kind:key`: the value (None: the ask failed) and when.
    static KNOWN: Mutex<Option<HashMap<String, (Option<Value>, u64)>>> = Mutex::new(None);
    /// Asks on their way, by `kind:key`.
    static ASKING: Mutex<Option<HashMap<String, u64>>> = Mutex::new(None);
    /// When the module was last found absent, by kind: a slow label never hides publisher checks.
    static ABSENT_AT: Mutex<Option<HashMap<&'static str, u64>>> = Mutex::new(None);

    /// What is kept for `slot`, while it is fresh: Known, or Missing for a failed ask.
    fn kept(slot: &str, now: u64) -> Option<Looked> {
        let known = KNOWN.lock().unwrap_or_else(|e| e.into_inner());
        let looked = match known.as_ref()?.get(slot)? {
            (Some(value), at) if now.saturating_sub(*at) < KEEP_S => Some(Looked::Known(value.clone())),
            (None, at) if now.saturating_sub(*at) < FAILED_S => Some(Looked::Missing),
            _ => None,
        };
        looked
    }

    /// The kept answer for `key`, never waiting: when none is kept, an ask is sent (one per key
    /// at a time) and this answers Checking until it is back. A call never blocks on the
    /// registry: the ask is asynchronous (`peer::ask`), sent from the module's call thread and
    /// answered later by the host's event loop, and the answer is only stored for a later call
    /// to read. No thread is spawned for it: a thread that calls another module waits on the
    /// host's main thread (peer.rs), and four such threads were the 2026-11-18 hang. No lock is
    /// held across the ask, whose answer may come back at once (not loaded) or inside another
    /// call's wait.
    fn kept_or_ask(kind: &'static str, key: &str, method: &'static str, wait: Duration) -> Looked {
        let now = super::now();
        let slot = format!("{kind}:{key}");
        if let Some(looked) = kept(&slot, now) {
            return looked;
        }
        // Not installed at all (package_manager's own list says so), or installed but not
        // loaded (nothing listens at its endpoint): said at once, rather than after the
        // host's wait for a module that isn't there (about 15 s).
        if installed() == Some(false) || peer::presence(MODULE) == peer::Presence::Down {
            return Looked::Missing;
        }
        let absent_at = ABSENT_AT.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(HashMap::new).get(kind).copied().unwrap_or(0);
        if now.saturating_sub(absent_at) < FAILED_S {
            return Looked::Missing;
        }
        {
            let mut asking = ASKING.lock().unwrap_or_else(|e| e.into_inner());
            let asking = asking.get_or_insert_with(HashMap::new);
            if asking.get(&slot).is_some_and(|at| now.saturating_sub(*at) < 60) {
                return Looked::Checking;
            }
            asking.insert(slot.clone(), now);
        }
        let stored = slot.clone();
        peer::ask(
            MODULE,
            method,
            &json!([key]),
            wait,
            Box::new(move |answer| {
                let now = super::now();
                let value = match answer {
                    Ok(answer) => {
                        // It answers `{success, value, error}`, perhaps as JSON text.
                        let answer = match answer.as_str().map(serde_json::from_str::<Value>) {
                            Some(Ok(parsed)) => parsed,
                            _ => answer,
                        };
                        (answer["success"] == true).then(|| answer["value"].clone()).filter(Value::is_object)
                    }
                    Err(_) => {
                        ABSENT_AT.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(HashMap::new).insert(kind, now);
                        None
                    }
                };
                KNOWN.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(HashMap::new).insert(stored.clone(), (value, now));
                ASKING.lock().unwrap_or_else(|e| e.into_inner()).get_or_insert_with(HashMap::new).remove(&stored);
            }),
        );
        // An ask refused at once (not loaded, held) was answered inside `ask`.
        kept(&slot, now).unwrap_or(Looked::Checking)
    }

    /// Whether the program_registry package is installed, from package_manager's list of
    /// installed modules (it reads its folders, at once): `Some(false)` only when that list was
    /// read and holds this names module but not program_registry; None while unknown (asked
    /// as before). Kept a minute; asked again without waiting.
    static INSTALLED: Mutex<Option<(Option<bool>, u64)>> = Mutex::new(None);
    /// When the list was last asked for (0: not on its way). An ask whose answer never comes
    /// is given up after a minute.
    static INSTALLED_ASKED_AT: AtomicU64 = AtomicU64::new(0);

    fn installed() -> Option<bool> {
        let kept = *INSTALLED.lock().unwrap_or_else(|e| e.into_inner());
        if kept.map_or(true, |(_, at)| super::now().saturating_sub(at) >= 60) {
            warm();
        }
        kept.and_then(|(listed, _)| listed)
    }

    /// Asks package_manager whether program_registry is installed, without waiting, so the first
    /// sheet after Names opens already knows. Called when the Names app reads its config.
    pub fn warm() {
        let now = super::now();
        let asked = INSTALLED_ASKED_AT.load(Ordering::SeqCst);
        if asked != 0 && now.saturating_sub(asked) < 60 {
            return;
        }
        if INSTALLED_ASKED_AT.compare_exchange(asked, now.max(1), Ordering::SeqCst, Ordering::SeqCst).is_err() {
            return;
        }
        peer::ask(
            "package_manager",
            "getInstalledModules",
            &json!([]),
            Duration::from_secs(5),
            Box::new(|answer| {
                let listed = answer.ok().and_then(|answer| super::package_listed(&answer, MODULE));
                *INSTALLED.lock().unwrap_or_else(|e| e.into_inner()) = Some((listed, super::now()));
                INSTALLED_ASKED_AT.store(0, Ordering::SeqCst);
            }),
        );
    }

    /// `program_label`'s value for `program` (base58), as far as is known now (`kept_or_ask`).
    pub fn label_state(program: &str) -> Looked {
        kept_or_ask("label", program, "program_label", LOOK)
    }

    /// `label_state`'s answer, or None while checking or when the registry can't say.
    pub fn label(program: &str) -> Option<Value> {
        label_state(program).known()
    }

    /// `verify_app`'s value for the Basecamp module `app`: whether its package is really
    /// published by the LNS name it names. The first check of a name derives it (Argon2, about
    /// a second) and reads its record, so it is Checking for a few seconds (`kept_or_ask`).
    pub fn publisher_state(app: &str) -> Looked {
        kept_or_ask("publisher", app, "verify_app", Duration::from_secs(15))
    }
}

/// The most a bridge deposit's fee may be, as `names bridge` caps it by default.
const BRIDGE_MAX_FEE: u64 = 100_000;
/// What a bridge plan that needs a split sets aside for the split's own fee, which the
/// node tells only once the split is made (866, 2,018 and 2,054 seen for one-input transfers).
const SPLIT_FEE_ALLOWANCE: u64 = 10_000;

/// The board answers kept at once (feeds, authors' pages, threads).
const MAX_BOARD_READS: usize = 48;
/// The board's CLI runs at once.
const MAX_BOARD_FETCHES: usize = 3;

/// Whether a `board_reads` key is a board answer (not the wallet's names or tokens).
fn is_board_key(key: &str) -> bool {
    ["feed:", "author:", "thread:"].iter().any(|kind| key.starts_with(kind))
}

/// The most tokens the wallet keeps added by address, per token program.
const MAX_WATCHED_TOKENS: usize = 64;

/// The tokens added by address for `program`: `[{definition, name}]`.
fn tokens_watched(program: &AccountId) -> Vec<Value> {
    let all = config_dir().map(|dir| load_object(&dir.join("tokens-watched.json"))).unwrap_or_default();
    all.get(&registry::account_text(program)).and_then(Value::as_array).cloned().unwrap_or_default()
}

fn save_tokens_watched(program: &AccountId, list: &[Value]) -> Result<(), String> {
    let dir = config_dir().ok_or("there is no config folder to keep the token list in")?;
    let path = dir.join("tokens-watched.json");
    let mut all = load_object(&path);
    all.insert(registry::account_text(program), Value::from(list.to_vec()));
    save_object(&path, &all);
    Ok(())
}

/// Sends made from this device, by hash: `{from, inputs, fee, at}`, for `chain_tx`.
/// Kept on disk, so a send is still followed after the module restarts.
/// The Logos Blockchain sends made here. A file that can't be read is set aside and told,
/// never written over by the next send (chain-sent-corrupt-file-silently-overwritten).
fn chain_sent() -> Map<String, Value> {
    config_dir().map(|dir| activity::load(&dir.join("chain-sent.json"))).unwrap_or_default()
}

/// Whether a send made here (`chain_sent`) is in a block: its inputs are spent, or for a
/// split whose inputs weren't known, its exact note is there.
fn chain_landed(hash: &str) -> Result<bool, String> {
    let Some(known) = chain_sent().remove(hash) else { return Err(NOT_SENT_HERE.to_owned()) };
    let inputs: Vec<String> = known["inputs"].as_array().into_iter().flatten().filter_map(|i| i.as_str().map(str::to_owned)).collect();
    let notes = chain::notes_of(&node::call("wallet_get_notes", json!([known["from"], ""]), node::QUICK)?);
    Ok(if inputs.is_empty() {
        let split = known["split"].as_str().and_then(|text| text.parse::<u128>().ok());
        split.is_some_and(|split| notes.values().any(|value| chain::amount(value) == split))
    } else {
        chain::spent(&inputs, &notes)
    })
}

/// What `chain_landed` says of a hash with no record here.
const NOT_SENT_HERE: &str = "not sent from here";

/// Whether the transaction `hash`, spending from `from`, is in a block, asked of the node
/// when no record of it is kept here: the inputs it stores for it are all spent.
fn chain_landed_asked(hash: &str, from: &str) -> Result<bool, String> {
    let stored = node::call("get_transaction", json!([hash]), node::QUICK)?;
    let inputs = chain::all_inputs(&stored);
    if inputs.is_empty() {
        return Err("the node doesn't show what that transaction spends".to_owned());
    }
    let notes = chain::notes_of(&node::call("wallet_get_notes", json!([from, ""]), node::QUICK)?);
    Ok(chain::spent(&inputs, &notes))
}

/// How long a send made here holds the notes it spends for itself: once in a block they
/// are gone anyway; one that never lands lets them go after this.
const NOTES_HELD_S: u64 = 15 * 60;

/// The notes of `from` that a recent send made here spends (`chain_sent` inputs), which
/// another transfer must not pick while it may still land.
fn chain_notes_in_use(from: &str) -> std::collections::HashSet<String> {
    let at = now();
    chain_sent()
        .values()
        .filter(|sent| sent["from"].as_str() == Some(from) && at.saturating_sub(sent["at"].as_u64().unwrap_or(0)) < NOTES_HELD_S)
        .flat_map(|sent| sent["inputs"].as_array().cloned().unwrap_or_default())
        .filter_map(|input| input.as_str().map(str::to_owned))
        .collect()
}

/// The refusal while a send made here still spends the notes a new one needs.
const IN_FLIGHT: &str = "Another transfer from this key is still waiting to land, and its notes can't be spent twice. Try again in a minute. Nothing was sent.";

/// A node's "not enough" for `from` while a send made here still spends some of its notes
/// (`notes`, the key's now): the key holds enough, its notes are in flight
/// (send-refusal-wording-concurrent: "doesn't hold enough" though it held 100,000).
fn in_flight_refusal(error: String, from: &str, notes: &Map<String, Value>) -> String {
    let short = error == chain::problem("wallet_transfer_funds", "not enough");
    if short && chain_notes_in_use(from).iter().any(|note| notes.contains_key(note)) {
        return IN_FLIGHT.to_owned();
    }
    // Held by the node for an inscription priced here (chain_inscribe.rs), not short.
    if short && chain_inscribe::plan_holds_notes_of(from, notes) {
        return chain_inscribe::HELD.to_owned();
    }
    error
}

/// Most blocks walked back from the node's tip to find a deposit whose call was cut off.
const DEPOSIT_SEARCH_BLOCKS: usize = 600;

/// The deposit `op_id` of `note` from `from` (the history's `entry`), made though its call
/// was cut off: its transaction's hash, found in the recent blocks' events, and the fee it
/// paid, from what the key's notes held when it was sent (kept with its pending record).
/// The hash is then kept like any send made here, so `chain_tx` can be asked of it.
/// `Err` (the busy mark) while the node's answers are still on their way (in a poll): the
/// caller tries again on the next one; `Ok(None)` when it isn't in the blocks walked.
fn deposit_made(op_id: &[u8; 32], from: &str, note: &str, entry: &Value) -> Result<Option<(String, Option<u128>)>, String> {
    let found = if node::reads_kept_now() {
        // A poll: the walk goes on by itself, each block asked from the last one's answer
        // (node::deposit_walk), so it never waits here and is never a block a poll.
        match node::deposit_walk(op_id, DEPOSIT_SEARCH_BLOCKS) {
            node::Walk::Found(hash) => Some(hash),
            node::Walk::Missing => None,
            node::Walk::Walking | node::Walk::Failed(_) => return Err(still_reading("where the deposit landed")),
        }
    } else {
        (|| {
            let mut block = node::call("get_cryptarchia_info", json!([]), node::QUICK).ok()?["tip"].as_str()?.to_owned();
            for _ in 0..DEPOSIT_SEARCH_BLOCKS {
                let events = node::call("get_block_events", json!([block]), node::QUICK).ok()?;
                if let Some(hash) = chain::deposit_in_events(&events, op_id) {
                    return Some(hash);
                }
                block = node::call("get_block", json!([block]), node::QUICK).ok()?["header"]["parent_block"].as_str()?.to_owned();
            }
            None
        })()
    };
    let Some(hash) = found else { return Ok(None) };
    let sent = chain_sent();
    // Cut off after its record was kept: that has its fee already.
    if let Some(known) = sent.get(&hash) {
        return Ok(Some((hash.clone(), known["fee"].as_str().and_then(|fee| fee.parse().ok()))));
    }
    let pending = sent.into_iter().find(|(key, sent)| key.starts_with("pending-") && sent["inputs"] == json!([note]) && sent["from"] == from);
    // Its fee from the transaction: one still on its way is waited for on the next poll, so the
    // record is never kept without it.
    let stored = match node::call("get_transaction", json!([hash]), node::QUICK) {
        Ok(tx) => Some(tx),
        Err(why) if is_busy(&why) => return Err(why),
        Err(_) => None,
    };
    let amount = entry["amount"].as_str().and_then(|amount| amount.parse::<u128>().ok());
    let fee = match (&stored, &pending, amount) {
        (Some(tx), Some((_, sent)), Some(amount)) => sent["notes"].as_object().and_then(|notes| chain::deposit_fee(tx, notes, amount)),
        _ => None,
    };
    let mut inputs = stored.as_ref().map(chain::all_inputs).unwrap_or_default();
    if inputs.is_empty() {
        inputs.push(note.to_owned());
    }
    chain_sent_add(&hash, json!({ "from": from, "inputs": inputs, "fee": fee.map(|f| f.to_string()), "at": entry["at"] }));
    if let Some((key, _)) = pending {
        chain_sent_remove(&key);
    }
    Ok(Some((hash, fee)))
}

/// Forgets a record `chain_sent_add` made (a deposit's pending one, once it has its hash).
fn chain_sent_remove(key: &str) {
    let Some(dir) = config_dir() else { return };
    let mut all = chain_sent();
    if all.remove(key).is_some() {
        save_object(&dir.join("chain-sent.json"), &all);
    }
}

/// Remembers a send; past `MAX_CACHED` sends the oldest is forgotten.
fn chain_sent_add(hash: &str, sent: Value) {
    let Some(dir) = config_dir() else { return };
    let mut all = chain_sent();
    while all.len() >= MAX_CACHED {
        let Some(oldest) = all.iter().min_by_key(|(_, s)| s["at"].as_u64().unwrap_or(0)).map(|(h, _)| h.clone()) else { break };
        all.remove(&oldest);
    }
    all.insert(hash.to_owned(), sent);
    save_object(&dir.join("chain-sent.json"), &all);
}

/// About what `shape` will cost paid from `from`, set in `plan` as `field` (decimal text, or
/// null when the node can't say), with `cannot_pay_fee: true` when the key's notes can't
/// pay it and its fee, and `in_flight: true` when they could but some are a send's from
/// here still on its way: asked of the node with stand-ins of the key's notes, less `skip`
/// and those a send from here still spends, so no real note is reserved (chain_fee.rs).
/// `Err` when the node refuses it as it would refuse the send (a recipient that isn't a key).
fn chain_fee_about(plan: &mut Value, field: &str, shape: &chain_fee::Shape, from: &str, skip: Option<&str>) -> Result<(), String> {
    plan[field] = Value::Null;
    // In a plan (`node::polled`) a read of the node still on its way makes the plan wait (busy),
    // never a plan shown without its fee.
    let notes = match node::call("wallet_get_notes", json!([from, ""]), node::QUICK) {
        Ok(reply) => chain::notes_of(&reply),
        Err(why) if is_busy(&why) => return Err(why),
        Err(_) => return Ok(()),
    };
    let busy = chain_notes_in_use(from);
    let (held_busy, free): (Vec<_>, Vec<_>) = notes.iter().filter(|(id, _)| skip != Some(id.as_str())).partition(|(id, _)| busy.contains(*id));
    let values = |notes: Vec<(&String, &Value)>| notes.into_iter().map(|(_, value)| chain::amount(value)).collect::<Vec<u128>>();
    let mut reading = None;
    let estimate = chain_fee::with_busy(shape, from, &values(free), &values(held_busy), |request| {
        let funded = node::call("wallet_fund_tx", json!([request]), node::QUICK);
        if let Err(why) = &funded {
            if is_busy(why) {
                reading = Some(why.clone());
            }
        }
        funded
    });
    if let Some(busy) = reading {
        return Err(busy);
    }
    match estimate? {
        chain_fee::Estimate::Fee(fee) => plan[field] = Value::from(fee.to_string()),
        chain_fee::Estimate::Short => plan["cannot_pay_fee"] = Value::Bool(true),
        chain_fee::Estimate::InFlight => plan["in_flight"] = Value::Bool(true),
        chain_fee::Estimate::Unknown => {}
    }
    Ok(())
}

/// About what one `leader_claim` will cost: its LeaderClaim op and a transfer from the
/// node's leader funding key, which names can't tell from the others, so the most any
/// key would pay with its own notes (chain_fee::claim_estimate).
fn chain_claim_fee_about() -> Value {
    let keys = node::call("wallet_get_known_addresses", json!([]), node::QUICK).unwrap_or_default();
    let held: Vec<(String, Vec<u128>)> = keys
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .take(MAX_WALLET_ACCOUNTS)
        .filter_map(|key| {
            let notes = node::call("wallet_get_notes", json!([key, ""]), node::QUICK).map(|reply| chain::notes_of(&reply)).ok()?;
            Some((key.to_owned(), notes.values().map(chain::amount).collect()))
        })
        .collect();
    chain_fee::claim_estimate(&held, |request| node::call("wallet_fund_tx", json!([request]), node::QUICK)).map_or(Value::Null, |fee| Value::from(fee.to_string()))
}

/// Basecamp's Logos Blockchain node (`blockchain_module`), for the chain methods. Asked through
/// `peer` (peer.rs): when the module isn't loaded the call fails at once, in words that say
/// nothing was sent, never after a 15 s wait on the module's one thread.
mod node {
    use super::{chain, peer, Value};
    use std::time::Duration;

    /// A read: the node answers from its own state.
    pub const QUICK: Duration = Duration::from_secs(15);
    /// A transfer or claim, which the node proves before it answers.
    pub const PROVING: Duration = Duration::from_secs(180);

    /// The node isn't loaded: nothing was sent. Says "isn't running", which the Names app
    /// reads as the node being off (its "Open the Blockchain app" line), and never "didn't
    /// answer", which the chain methods read as "it may have been taken".
    pub const NOT_LOADED: &str = "Basecamp's Logos Blockchain node isn't running (blockchain_module isn't loaded). Start it in Basecamp's Blockchain app, then try again. Nothing was sent.";
    /// It gave no answer a moment ago, so it wasn't asked: nothing was sent.
    pub const HELD: &str = "Basecamp's Logos Blockchain node isn't running or isn't answering: it gave no answer to the last ask, so it isn't asked again for half a minute. Nothing was sent.";
    /// Asked from a thread names spawned, which could freeze the module: refused, nothing sent.
    pub const OFF_THREAD: &str = "the Logos Blockchain node can only be asked from the module's own call thread, so it wasn't asked. Nothing was sent.";
    /// Sent, no answer: it may have been taken (the chain methods rely on these words).
    pub const NO_ANSWER: &str = "Basecamp's Logos Blockchain node didn't answer. Install the Blockchain app and start its node.";

    pub fn call(method: &str, args: Value, wait: Duration) -> Result<Value, String> {
        // A read made for a poll (`polled`): answered from what the node last said, asked
        // without waiting (`kept`). A send's or a claim's own reads are never: they wait for
        // the node's answer now, as before.
        if wait <= QUICK && POLLED.with(std::cell::Cell::get) && kept_reads() {
            return kept(method, args);
        }
        let answer = answer_of(method, peer::call(chain::MODULE, method, &args, wait));
        // A call outside a poll is a press (a send, a claim, an account made or renamed, a plan):
        // what was kept for the polls is asked again, and an answer still on its way is dropped.
        forget();
        answer
    }

    /// What `call` makes of the module's answer (or of why there is none).
    fn answer_of(method: &str, answer: Result<Value, peer::Failure>) -> Result<Value, String> {
        let answer = answer.map_err(|failure| match failure {
            peer::Failure::NotLoaded => NOT_LOADED.to_owned(),
            peer::Failure::Held => HELD.to_owned(),
            peer::Failure::OffThread => OFF_THREAD.to_owned(),
            peer::Failure::NoAnswer(_) => NO_ANSWER.to_owned(),
            peer::Failure::Refused(why) => chain::problem(method, &why),
        })?;
        chain::unwrap(method, answer)
    }

    // ── The polls' reads: asked without waiting, answered from what the node last said ──
    //
    // The third stall (2026-11-18, build 31153da, on a Basecamp with blockchain_module loaded):
    // as Names opened, `loadChain` made chain_status, chain_accounts, chain_stake and chain_claim
    // ask the node and wait for it (up to 15 s each ask) on the module's one thread. A node that
    // is loaded and slow (or silent) held every call the app had sent behind them past
    // Basecamp's 20 s: app_grants, backup_status, file_sha256, the 3 s polls. A wait for another
    // module's answer can't move to a thread names spawns (peer.rs: such a thread waits for the
    // main thread, the 2026-11-18 hang), so a poll's read is an ask (`peer::ask`): sent from the
    // call's thread, answered later by the host's event loop into `Reads`, and the call answers
    // at once with what the node said last (`KEEP` old at most, else asked again meanwhile), or
    // busy ("still reading") before its first answer; the app reads again on its next poll.

    thread_local! {
        /// Set while a poll runs (`polled`): its node reads are `kept` reads.
        static POLLED: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    }

    /// Whether a node read made now is a poll's kept read (`polled`, in a module build).
    pub fn reads_kept_now() -> bool {
        POLLED.with(std::cell::Cell::get) && kept_reads()
    }

    /// Where a cut-off deposit's walk down the chain is (`deposit_walk`).
    #[derive(Clone, Debug, PartialEq)]
    pub enum Walk {
        Walking,
        Found(String),
        /// Not in the blocks walked.
        Missing,
        /// A read failed: the next call starts it again.
        Failed(String),
    }

    /// The walk for deposit `op_id`, from the tip down `blocks` blocks, looking in each block's
    /// events for it. Started by the first call; each step is asked from the last one's answer, on
    /// the host's event loop, so it goes on between polls without any call waiting for it.
    pub fn deposit_walk(op_id: &[u8; 32], blocks: usize) -> Walk {
        let reads = store();
        let key = super::registry::hex(op_id);
        let generation = {
            let mut store = lock(&reads);
            match store.walks.get(&key) {
                Some(Walk::Failed(_)) | None => {}
                Some(walk) => return walk.clone(),
            }
            store.walks.insert(key.clone(), Walk::Walking);
            store.generation
        };
        let (into, op) = (std::sync::Arc::clone(&reads), *op_id);
        walk_ask(std::sync::Arc::clone(&reads), generation, key.clone(), "get_cryptarchia_info", serde_json::json!([]), move |info| match info["tip"].as_str() {
            Some(tip) => walk_block(into, generation, op, tip.to_owned(), blocks),
            None => walk_end(&into, generation, &super::registry::hex(&op), Walk::Failed("the node didn't say its tip".to_owned())),
        });
        let walk = lock(&reads).walks.get(&key).cloned().unwrap_or(Walk::Walking);
        walk
    }

    fn walk_end(reads: &Reads, generation: u64, key: &str, walk: Walk) {
        let mut store = lock(reads);
        if store.generation == generation {
            store.walks.insert(key.to_owned(), walk);
        }
    }

    fn walk_block(reads: std::sync::Arc<Reads>, generation: u64, op: [u8; 32], block: String, left: usize) {
        let key = super::registry::hex(&op);
        let into = std::sync::Arc::clone(&reads);
        walk_ask(reads, generation, key.clone(), "get_block_events", serde_json::json!([block.clone()]), move |events| {
            if let Some(hash) = chain::deposit_in_events(&events, &op) {
                return walk_end(&into, generation, &key, Walk::Found(hash));
            }
            if left <= 1 {
                return walk_end(&into, generation, &key, Walk::Missing);
            }
            let next = std::sync::Arc::clone(&into);
            walk_ask(into, generation, key.clone(), "get_block", serde_json::json!([block]), move |found| match found["header"]["parent_block"].as_str() {
                Some(parent) => walk_block(next, generation, op, parent.to_owned(), left - 1),
                None => walk_end(&next, generation, &key, Walk::Missing),
            });
        });
    }

    /// Asks the node `method(args)` for the walk; `then` gets its answer, a failure ends the walk.
    fn walk_ask(reads: std::sync::Arc<Reads>, generation: u64, key: String, method: &'static str, args: Value, then: impl FnOnce(Value) + Send + 'static) {
        if lock(&reads).generation != generation {
            return;
        }
        peer::ask(
            chain::MODULE,
            method,
            &args,
            ASK_WAIT,
            Box::new(move |answer| match answer_of(method, answer) {
                Ok(value) => then(value),
                Err(why) => walk_end(&reads, generation, &key, Walk::Failed(why)),
            }),
        );
    }

    /// Runs `body`, a poll (chain_status, chain_accounts, …): its reads of the node never wait.
    pub fn polled<R>(body: impl FnOnce() -> R) -> R {
        let was = POLLED.with(|polled| polled.replace(true));
        let out = body();
        POLLED.with(|polled| polled.set(was));
        out
    }

    /// How long an answer is used before the node is asked again (the app polls every 5 s).
    pub const KEEP: Duration = Duration::from_secs(5);
    /// The oldest answer shown while a newer one is on its way; older, the poll answers busy.
    const STALE_AT_MOST: Duration = Duration::from_secs(30);
    /// For an answer that never changes (a block, its events, a transaction by its hash).
    const KEEP_FIXED: Duration = Duration::from_secs(3600);
    const FIXED: [&str; 3] = ["get_block", "get_block_events", "get_transaction"];
    /// How long an ask may wait for the node.
    const ASK_WAIT: Duration = QUICK;
    /// How long the first ask may take, until an ask was sent without the host first acquiring
    /// the module's object (which happens on the call's thread, and waits as long as the ask may
    /// for a module that is loaded but busy): a short first ask holds the thread a second at most.
    const FIRST_ASK_WAIT: Duration = Duration::from_secs(1);
    /// A sending this quick found the module's object already acquired.
    const QUICK_SEND: Duration = Duration::from_millis(100);
    /// An ask whose sending held the call's thread this long (the host acquiring the module's
    /// object before it sends) leaves the node alone for `peer::HOLD`.
    const SLOW_ASK: Duration = Duration::from_millis(500);
    /// The most answers kept (the oldest go first).
    const MOST: usize = 1024;

    #[derive(Default)]
    struct Kept {
        answer: Option<(Result<Value, String>, std::time::Instant)>,
        asked: Option<std::time::Instant>,
    }

    #[derive(Default)]
    pub struct Store {
        kept: std::collections::HashMap<String, Kept>,
        /// Bumped by `forget`: an answer to an ask sent before it is dropped.
        generation: u64,
        /// An ask was sent without the host acquiring the module's object first (QUICK_SEND).
        reached: bool,
        /// Cut-off deposits' walks down the chain, by op id (`deposit_walk`).
        walks: std::collections::HashMap<String, Walk>,
    }

    #[derive(Default)]
    pub struct Reads(std::sync::Mutex<Store>);

    fn lock(reads: &Reads) -> std::sync::MutexGuard<'_, Store> {
        reads.0.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
    }

    /// The answer kept for `method(args)`: fresh, or the last one while it is asked again, or
    /// busy before the first. Never waits: the ask is sent and its answer stored when it comes.
    /// No lock is held while it is sent (its answer may come back at once).
    fn kept(method: &str, args: Value) -> Result<Value, String> {
        let reads = store();
        let key = format!("{method}\u{0}{args}");
        let (generation, wait) = {
            let mut store = lock(&reads);
            let generation = store.generation;
            let wait = if store.reached { ASK_WAIT } else { FIRST_ASK_WAIT };
            let kept = &mut store.kept;
            if let Some(slot) = kept.get(&key) {
                if let Some((answer, at)) = &slot.answer {
                    // An hour only for a real answer that can't change (a block, a transaction);
                    // a failure, or a transaction not stored yet (null), is asked again after
                    // KEEP like any other read.
                    let keep = if FIXED.contains(&method) && answer.as_ref().is_ok_and(|value| !value.is_null()) { KEEP_FIXED } else { KEEP };
                    if at.elapsed() < keep {
                        return answer.clone();
                    }
                }
                // Asked already, its answer not back yet (the host gives it up after its wait).
                if slot.asked.is_some_and(|at| at.elapsed() < ASK_WAIT + Duration::from_secs(5)) {
                    return last_or_busy(slot);
                }
            }
            if kept.len() >= MOST {
                let oldest = kept.iter().min_by_key(|(_, slot)| slot.answer.as_ref().map(|(_, at)| *at)).map(|(key, _)| key.clone());
                if let Some(oldest) = oldest {
                    kept.remove(&oldest);
                }
            }
            kept.entry(key.clone()).or_default().asked = Some(std::time::Instant::now());
            (generation, wait)
        };
        let sending = std::time::Instant::now();
        let into = std::sync::Arc::clone(&reads);
        let (stored, asked_for) = (key.clone(), method.to_owned());
        let answered_at_once = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let at_once = std::sync::Arc::clone(&answered_at_once);
        // The short first ask's wait bounds the host acquiring the node's object, but the SDK has
        // one timeout for the whole call: its running out says nothing about the node, so it
        // neither holds the module nor is kept as "didn't answer"; the next poll asks again,
        // with the full wait.
        let short = wait == FIRST_ASK_WAIT;
        let done: peer::Done = Box::new(move |answer| {
            at_once.store(true, std::sync::atomic::Ordering::SeqCst);
            let mut store = lock(&into);
            if store.generation != generation {
                return;
            }
            if short && matches!(answer, Err(peer::Failure::NoAnswer(_))) {
                store.reached = true;
                if let Some(slot) = store.kept.get_mut(&stored) {
                    slot.asked = None;
                }
                return;
            }
            let answer = answer_of(&asked_for, answer);
            let slot = store.kept.entry(stored).or_default();
            slot.answer = Some((answer, std::time::Instant::now()));
            slot.asked = None;
        });
        if short {
            peer::ask_unheld(chain::MODULE, method, &args, wait, done);
        } else {
            peer::ask(chain::MODULE, method, &args, wait, done);
        }
        let took = sending.elapsed();
        let mut store = lock(&reads);
        // Refused before it was sent (not loaded, held): nothing is learnt about the host.
        let sent = !answered_at_once.load(std::sync::atomic::Ordering::SeqCst);
        if took >= SLOW_ASK {
            // The host held the thread acquiring the module's object: leave it alone a while, and
            // ask with the short wait again once it may be asked.
            store.reached = false;
            drop(store);
            peer::hold(chain::MODULE);
            store = lock(&reads);
        } else if sent && took < QUICK_SEND {
            store.reached = true;
        }
        store.kept.get(&key).map_or_else(|| Err(busy()), last_or_busy)
    }

    /// The last answer while a newer one is on its way (if it isn't too old), else busy.
    fn last_or_busy(slot: &Kept) -> Result<Value, String> {
        match &slot.answer {
            Some((answer, at)) if at.elapsed() < STALE_AT_MOST => answer.clone(),
            _ => Err(busy()),
        }
    }

    fn busy() -> String {
        super::still_reading("what the Logos Blockchain node says")
    }

    /// Forgets every answer kept, and drops the answers on their way (a press changed the node).
    pub fn forget() {
        if kept_reads() {
            let reads = store();
            let mut store = lock(&reads);
            store.kept.clear();
            store.walks.clear();
            store.generation += 1;
        }
    }

    #[cfg(not(test))]
    fn kept_reads() -> bool {
        true
    }

    #[cfg(not(test))]
    fn store() -> std::sync::Arc<Reads> {
        static READS: std::sync::OnceLock<std::sync::Arc<Reads>> = std::sync::OnceLock::new();
        std::sync::Arc::clone(READS.get_or_init(Default::default))
    }

    // In unit tests a poll's reads wait for the stand-in node, as before, unless the test runs the
    // module as the host does (`reads_as_in_a_build`); each test thread keeps its own answers.
    #[cfg(test)]
    thread_local! {
        static KEPT_READS: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
        static READS: std::cell::RefCell<std::sync::Arc<Reads>> = std::cell::RefCell::new(Default::default());
    }

    /// From now on in this test thread a poll's node reads are asked and kept, as in a build.
    #[cfg(test)]
    pub fn reads_as_in_a_build() {
        KEPT_READS.with(|on| on.set(true));
    }

    #[cfg(test)]
    fn kept_reads() -> bool {
        KEPT_READS.with(std::cell::Cell::get)
    }

    #[cfg(test)]
    fn store() -> std::sync::Arc<Reads> {
        READS.with(|reads| std::sync::Arc::clone(&reads.borrow()))
    }

    // Stands in for the node in unit tests: a test sets each method's answer, and what was
    // asked is kept. Reached through peer's stand-in host, so the gate is the module build's.
    #[cfg(test)]
    thread_local! {
        pub static ANSWERS: std::cell::RefCell<std::collections::HashMap<String, Value>> = std::cell::RefCell::new(std::collections::HashMap::new());
        pub static ASKED: std::cell::RefCell<Vec<(String, Value)>> = const { std::cell::RefCell::new(Vec::new()) };
    }

    #[cfg(test)]
    pub fn answer(method: &str, args: &Value) -> Result<Value, peer::Failure> {
        ASKED.with(|asked| asked.borrow_mut().push((method.to_owned(), args.clone())));
        let answer = ANSWERS.with(|answers| answers.borrow().get(method).cloned());
        answer.ok_or_else(|| peer::Failure::NoAnswer("no answer set".to_owned()))
    }
}

/// Stands in for the Program Registry in unit tests: a test sets the label.
#[cfg(test)]
mod program_registry {
    use super::{Looked, Value};

    thread_local! {
        pub static LABEL: std::cell::RefCell<Option<Value>> = const { std::cell::RefCell::new(None) };
    }

    thread_local! {
        /// Set: every ask is still on its way (Checking).
        pub static CHECKING: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    }

    fn looked(value: Option<Value>) -> Looked {
        match value {
            _ if CHECKING.with(std::cell::Cell::get) => Looked::Checking,
            Some(value) => Looked::Known(value),
            None => Looked::Missing,
        }
    }

    pub fn label_state(_program: &str) -> Looked {
        looked(LABEL.with(|label| label.borrow().clone()))
    }

    pub fn label(program: &str) -> Option<Value> {
        label_state(program).known()
    }

    thread_local! {
        pub static PUBLISHER: std::cell::RefCell<Option<Value>> = const { std::cell::RefCell::new(None) };
    }

    pub fn publisher_state(_app: &str) -> Looked {
        looked(PUBLISHER.with(|publisher| publisher.borrow().clone()))
    }

    pub fn warm() {}
}

