    /// A bridge's account is read afresh between two asks of its receipt: the balance then
    /// holds its credit exactly when it arrives. A mint between the asks, or an ask LEZ
    /// doesn't answer, leaves the account unread this time (its credit would otherwise be
    /// told twice, as the bridge and as money that arrived).
    #[test]
    fn a_bridges_account_is_read_between_two_asks_of_its_receipt() {
        let names = fresh();
        let dir = config_dir().unwrap();
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let account = [5_u8; 32];
        let to = format!("Public/{}", registry::account_text(&account));
        registry::BALANCES.with(|held| held.borrow_mut().push((account, 23_000)));
        let id = activity::add(&dir, now(), json!({ "kind": "bridge", "chain": "logos", "to": to, "amount": "3000",
            "note": "11".repeat(32), "channel": "00".repeat(32), "state": "in_block" }));
        let receipt = activity::bridge_receipt(&activity::all(&dir)[0]).unwrap();
        let state = || activity::all(&dir).into_iter().find(|e| e["id"] == id.as_str()).unwrap()["state"].as_str().unwrap().to_owned();
        let stale = [(to.clone(), 20_000_u128), ("Public/other".to_owned(), 7)];
        // Each step below is a later round, when the receipt is due again.
        let due_again = || names.receipt_asks.lock().unwrap().clear();
        // Not minted: the account is read afresh (the wallet's read may be older).
        assert_eq!(names.settle_activity(&dir, "seq", &stale, registry::Deadline::after(cli::CALL_BUDGET)), [(to.clone(), 23_000), ("Public/other".to_owned(), 7)]);
        assert_eq!(state(), "in_block");
        // LEZ doesn't answer for the receipt: the account isn't read this time.
        due_again();
        registry::MINTED_UNREAD.with(|unread| unread.set(true));
        assert_eq!(names.settle_activity(&dir, "seq", &stale, registry::Deadline::after(cli::CALL_BUDGET)), [("Public/other".to_owned(), 7)]);
        registry::MINTED_UNREAD.with(|unread| unread.set(false));
        assert_eq!(state(), "in_block");
        // Minted between the first ask and the second: arrived, and the account isn't read this time.
        due_again();
        let next = registry::MINTED_ASKED.with(std::cell::Cell::get);
        registry::MINTED.with(|minted| minted.borrow_mut().push((receipt, next + 1)));
        assert_eq!(names.settle_activity(&dir, "seq", &stale, registry::Deadline::after(cli::CALL_BUDGET)), [("Public/other".to_owned(), 7)]);
        assert_eq!(state(), "arrived");
        // Arrived, it isn't asked again; the account is the wallet's read.
        due_again();
        assert_eq!(names.settle_activity(&dir, "seq", &stale, registry::Deadline::after(cli::CALL_BUDGET)), stale);
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// bridges-followed-30-days-cost-receipt-reads: every balance read asked every followed
    /// bridge's receipt twice, for 30 days. Now an overdue bridge is asked hourly, unless its
    /// account's balance rose in a way nothing explains; then at once, so a mint in between
    /// is still told once, as the bridge arriving late, never also as money that arrived.
    #[test]
    fn an_overdue_bridge_is_asked_on_its_schedule_or_when_its_account_rises() {
        let names = fresh();
        let dir = config_dir().unwrap();
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let account = [6_u8; 32];
        let to = format!("Public/{}", registry::account_text(&account));
        registry::BALANCES.with(|held| held.borrow_mut().push((account, 10_000)));
        let three_days = 3 * 24 * 3600;
        let id = activity::add(&dir, now() - three_days, json!({ "kind": "bridge", "chain": "logos", "to": to, "amount": "3000",
            "note": "12".repeat(32), "channel": "00".repeat(32), "state": "in_block" }));
        let receipt = activity::bridge_receipt(&activity::all(&dir)[0]).unwrap();
        let asked = || registry::MINTED_ASKED.with(std::cell::Cell::get);
        let settle = |balance: u128| {
            let rows = names.settle_activity(&dir, "seq", &[(to.clone(), balance)], registry::Deadline::after(cli::CALL_BUDGET));
            // Noted as the module notes it: under the zone in use's marks, with its entries.
            names.note_lez(&rows);
            rows
        };
        // First round: asked (never asked before), around a fresh read; the mark is set.
        let first = asked();
        assert_eq!(settle(10_000), [(to.clone(), 10_000)]);
        assert_eq!(asked() - first, 2, "before and after the fresh read");
        // Rounds with nothing new: not asked, the wallet's read noted as it is.
        let quiet = asked();
        for _ in 0..5 {
            assert_eq!(settle(10_000), [(to.clone(), 10_000)]);
        }
        assert_eq!(asked(), quiet, "an overdue bridge isn't asked on every balance read");
        // Minted meanwhile: the account rose, so the receipt is asked now, whatever the hour.
        registry::MINTED.with(|minted| minted.borrow_mut().push((receipt, 0)));
        registry::BALANCES.with(|held| held.borrow_mut().iter_mut().for_each(|(id, held)| if *id == account { *held = 13_000 }));
        assert_eq!(settle(13_000), [(to.clone(), 13_000)]);
        let all = activity::all(&dir);
        let bridge = all.iter().find(|e| e["id"] == id.as_str()).unwrap();
        assert_eq!((bridge["state"].as_str(), bridge["late"].as_bool()), (Some("arrived"), Some(true)), "{bridge}");
        assert!(!all.iter().any(|e| e["kind"] == "arrived"), "the credit is the bridge's, told once: {all:?}");
        // The schedule itself: every minute while it waits, hourly once overdue.
        assert!(activity::receipt_due(60, None, 1_000));
        assert!(!activity::receipt_due(60, Some(990), 1_000));
        assert!(activity::receipt_due(60, Some(940), 1_000));
        assert!(!activity::receipt_due(three_days, Some(10_000 - 600), 10_000));
        assert!(activity::receipt_due(three_days, Some(10_000 - 3_600), 10_000));
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// deposit-lost-from-activity-on-unload: names unloaded while chain_bridge waited on
    /// the node: the exact note was spent, and neither chain-sent nor the history had it.
    #[test]
    fn a_deposit_cut_off_mid_call_is_kept_and_settled_by_its_note() {
        const A640: &str = "a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6";
        let mut names = fresh();
        let key = "4d".repeat(32);
        let to = "7wx3U7qMRWopjKXH67t9WpuNiNyB12pXUhB6CNA1LznR";
        node_answers("wallet_get_notes", json!({ "notes": [{ "id": "a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6", "value": "640080" }, { "id": "fee1", "value": "5000000" }] }));
        node_answers("get_channel_state", json!({ "configuration_threshold": 3 }));
        // No answer, as when names is unloaded while the node proves (the real run's error
        // was the node "didn't answer", and the deposit had been made).
        node::ANSWERS.with(|answers| answers.borrow_mut().remove("channel_deposit_with_notes"));
        let cut = parsed(&names.chain_bridge(key.clone(), format!("Public/{to}"), "640,080".into(), true));
        assert_eq!(cut["success"], false, "{cut}");
        let mine = |names: &mut Names| parsed(&names.activity(key.clone()))["value"].as_array().unwrap().iter().find(|e| e["amount"] == "640080").cloned();
        let kept = mine(&mut names).expect("the deposit is in the history");
        assert_eq!((kept["state"].as_str(), kept["note"].as_str(), kept["hash"].clone()), (Some("sending"), Some("a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6"), Value::Null), "{kept}");
        // Its note stays held: it isn't deposited twice.
        let again = parsed(&names.chain_bridge(key.clone(), format!("Public/{to}"), "640,080".into(), true));
        assert!(again["error"].as_str().unwrap().contains("still using its note"), "{again}");
        // The node spent the note: the deposit was made. bridge-settled-after-unload-has-no-hash-or-fee:
        // its transaction is found in a block's events by the deposit's op id, with its fee.
        let op: Vec<u8> = registry::unhex(kept["op_id"].as_str().unwrap()).unwrap();
        let hash = "7a".repeat(32);
        node_answers("get_cryptarchia_info", json!({ "tip": "b2", "height": 2 }));
        node_answers("get_block", json!({ "header": { "parent_block": "b1" } }));
        node_answers("get_block_events", json!([{ "Tx": { "tx_hash": hash, "op_id": op, "payload": { "Deposit": { "amount": 640080 } } } }]));
        node_answers("get_transaction", json!({ "mantle_tx": { "ops": [
            { "opcode": 18, "payload": { "inputs": [A640] } },
            { "opcode": 0, "payload": { "inputs": ["fee1"], "outputs": [{ "value": 4998386 }] } }] } }));
        node_answers("wallet_get_notes", json!({ "notes": [{ "id": "fee2", "value": "4998386" }] }));
        let settled = mine(&mut names).unwrap();
        assert_eq!((settled["state"].as_str(), settled["hash"].as_str(), settled["fee"].as_str()), (Some("in_block"), Some(hash.as_str()), Some("1614")), "{settled}");
        assert_eq!(parsed(&names.chain_tx(hash.clone()))["value"], json!({ "hash": hash, "state": "in_block", "fee": "1614" }));
        // A refusal, by contrast, leaves no record and holds nothing.
        node_answers("wallet_get_notes", json!({ "notes": [{ "id": "b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7", "value": "700000" }, { "id": "fee3", "value": "5000000" }] }));
        node_refuses("channel_deposit_with_notes", "invalid public key");
        assert_eq!(parsed(&names.chain_bridge(key.clone(), format!("Public/{to}"), "700,000".into(), true))["success"], false);
        let refused = parsed(&names.activity(key.clone()))["value"].as_array().unwrap().iter().find(|e| e["amount"] == "700000").cloned().unwrap();
        assert_eq!(refused["state"], "failed", "{refused}");
        assert!(!chain_notes_in_use(&key).contains("b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7b7"));
    }

    // ── Review of names-stall-3 (2026-11-19): the polls' node reads, as in a module build ──

    /// Review (2): a Logos send that landed is never written "unknown" because the node's answer
    /// was still on its way: the host delivers an ask's answer after the call returned
    /// (`stand_in::set_deferred`), so the first poll reads busy; the entry stays sending and
    /// settles in_block once the answers are there.
    #[test]
    fn review_a_landed_logos_send_is_never_written_unknown_while_the_nodes_answer_is_on_its_way() {
        let mut names = fresh();
        node::reads_as_in_a_build();
        peer::stand_in::set_deferred(chain::MODULE, true);
        let dir = config_dir().unwrap();
        let old = activity::add(&dir, now() - activity::SENDING_WAIT_S - 1, json!({ "kind": "send", "chain": "logos", "from": NODE_KEY, "to": "39".repeat(32), "amount": "700", "hash": "cc".repeat(32) }));
        node_answers("get_transaction", json!({ "mantle_tx": { "ops": [{ "opcode": 0, "payload": { "inputs": ["n700"], "outputs": [{ "value": 700 }] } }] } }));
        node_answers("wallet_get_notes", json!({ "notes": [{ "id": "n9", "value": "93798" }] }));
        let state = |id: &str| activity::all(&dir).into_iter().find(|e| e["id"] == id).unwrap()["state"].clone();
        let mut rounds = 0;
        while state(&old) == "sending" && rounds < 5 {
            names.activity(String::new());
            assert_ne!(state(&old), "unknown", "written unknown on round {rounds} while the node's answer was on its way");
            peer::stand_in::run_event_loop();
            rounds += 1;
        }
        assert_eq!(state(&old), "in_block");
        peer::stand_in::set_deferred(chain::MODULE, false);
    }

    /// Review (2): a deposit cut off mid-call settles with its hash and fee in a module build too:
    /// while the node's answers are on their way it stays sending (never in_block without them),
    /// and the walk down the chain goes on by itself between polls.
    #[test]
    fn review_a_cut_off_deposit_settles_with_its_hash_and_fee_when_the_nodes_answers_come_later() {
        const A640: &str = "a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6a6";
        let mut names = fresh();
        let key = "4d".repeat(32);
        let to = "7wx3U7qMRWopjKXH67t9WpuNiNyB12pXUhB6CNA1LznR";
        node_answers("wallet_get_notes", json!({ "notes": [{ "id": A640, "value": "640080" }, { "id": "fee1", "value": "5000000" }] }));
        node_answers("get_channel_state", json!({ "configuration_threshold": 3 }));
        node::ANSWERS.with(|answers| answers.borrow_mut().remove("channel_deposit_with_notes"));
        assert_eq!(parsed(&names.chain_bridge(key.clone(), format!("Public/{to}"), "640,080".into(), true))["success"], false);
        let mine = |names: &mut Names| parsed(&names.activity(key.clone()))["value"].as_array().unwrap().iter().find(|e| e["amount"] == "640080").cloned().unwrap();
        let kept = mine(&mut names);
        let op: Vec<u8> = registry::unhex(kept["op_id"].as_str().unwrap()).unwrap();
        let hash = "7a".repeat(32);
        // From here, as the host runs the module: the polls' reads are asks answered later.
        node::reads_as_in_a_build();
        peer::stand_in::set_deferred(chain::MODULE, true);
        node_answers("get_cryptarchia_info", json!({ "tip": "b3", "height": 3 }));
        node_answers("get_block", json!({ "header": { "parent_block": "b2" } }));
        node_answers("get_block_events", json!([{ "Tx": { "tx_hash": hash, "op_id": op, "payload": { "Deposit": { "amount": 640080 } } } }]));
        node_answers("get_transaction", json!({ "mantle_tx": { "ops": [
            { "opcode": 18, "payload": { "inputs": [A640] } },
            { "opcode": 0, "payload": { "inputs": ["fee1"], "outputs": [{ "value": 4998386 }] } }] } }));
        node_answers("wallet_get_notes", json!({ "notes": [{ "id": "fee2", "value": "4998386" }] }));
        let mut settled = mine(&mut names);
        let mut rounds = 0;
        while settled["state"] == "sending" && rounds < 8 {
            peer::stand_in::run_event_loop();
            settled = mine(&mut names);
            assert!(settled["state"] == "sending" || settled["hash"].is_string(), "settled without its hash on round {rounds}: {settled}");
            rounds += 1;
        }
        assert_eq!((settled["state"].as_str(), settled["hash"].as_str(), settled["fee"].as_str()), (Some("in_block"), Some(hash.as_str()), Some("1614")), "{settled}");
        peer::stand_in::set_deferred(chain::MODULE, false);
    }

    /// Review (1): a failed read of a block or a transaction isn't kept for the hour a real one is:
    /// after KEEP it is asked again, and the node's later answer is the one used.
    #[test]
    fn review_a_failed_read_of_a_transaction_is_asked_again_after_a_moment_not_kept_an_hour() {
        node::reads_as_in_a_build();
        peer::stand_in::set_deferred(chain::MODULE, true);
        let ask = || node::polled(|| node::call("get_transaction", json!(["dd".repeat(32)]), node::QUICK));
        // What the node's answer reads as, asked outside a poll (which also forgets what was kept).
        let tx = json!({ "mantle_tx": { "ops": [] } });
        node_answers("get_transaction", tx.clone());
        let expected = node::call("get_transaction", json!(["dd".repeat(32)]), node::QUICK);
        assert!(expected.is_ok(), "{expected:?}");
        node_refuses("get_transaction", "No transaction found for hash");
        assert!(ask().is_err_and(|why| is_busy(&why)));
        peer::stand_in::run_event_loop();
        let failed = ask();
        assert!(failed.as_ref().is_err_and(|why| !is_busy(why)), "{failed:?}");
        // The node stores it a moment later.
        node_answers("get_transaction", tx);
        std::thread::sleep(node::KEEP + std::time::Duration::from_millis(200));
        let _ = ask();
        peer::stand_in::run_event_loop();
        assert_eq!(ask(), expected, "the node's later answer");
        peer::stand_in::set_deferred(chain::MODULE, false);
    }

    /// Review (7): the first ask's short wait (1 s, to bound the host acquiring the node's object)
    /// is also the SDK's whole-call timeout. A healthy node that takes 2 s to answer is not taken
    /// for one that doesn't answer: no "didn't answer", no hold on a press meanwhile, and its
    /// answer is shown once it comes.
    #[test]
    fn review_a_slow_healthy_node_is_not_held_or_said_not_to_answer_after_the_short_first_ask() {
        let mut names = fresh();
        node::reads_as_in_a_build();
        peer::stand_in::hold_failures();
        node_answers("get_cryptarchia_info", json!({ "tip": "ab", "height": 7, "slot": 9, "mode": "Online" }));
        node_answers("get_time_info", json!({ "slot": 9, "epoch": 0 }));
        peer::stand_in::set_slow(chain::MODULE, Some(std::time::Duration::from_secs(2)));
        let started = std::time::Instant::now();
        let shown = loop {
            let status = parsed(&names.chain_status());
            assert!(status["busy"] == true || status["success"] == true, "said at {:?}: {status}", started.elapsed());
            if status["success"] == true {
                break status;
            }
            if started.elapsed() > std::time::Duration::from_millis(1300) && started.elapsed() < std::time::Duration::from_millis(1600) {
                // After the first ask's 1 s ran out: a press isn't refused as held.
                let press = node::call("get_time_info", json!([]), node::QUICK);
                assert!(press.as_ref().is_ok_and(|_| true) || !press.as_ref().unwrap_err().contains("isn't asked again"), "{press:?}");
            }
            assert!(started.elapsed() < std::time::Duration::from_secs(12), "the slow node's answer never came: {status}");
            std::thread::sleep(std::time::Duration::from_millis(250));
        };
        assert_eq!(shown["value"]["height"], 7, "{shown}");
        peer::stand_in::set_slow(chain::MODULE, None);
    }

    /// Review (4): a background read under way when its value was forgotten (a claim or a burn
    /// signed, another wallet) never puts its older value back afterwards; the next call reads
    /// afresh and shows the new value.
    #[test]
    fn review_a_background_read_from_before_a_forget_never_comes_back_after_it() {
        let names = fresh();
        let key = format!("{BRIDGE_NET_KEY}test");
        let every = std::time::Duration::from_secs(60);
        let _ = names.read_in_background(key.clone(), every, || {
            std::thread::sleep(std::time::Duration::from_millis(400));
            Ok(json!("before the claim"))
        });
        // The claim is signed while that read runs.
        names.board_reads.lock().unwrap().clear();
        std::thread::sleep(std::time::Duration::from_millis(700));
        let mut shown = Value::Null;
        for _ in 0..40 {
            shown = names.read_in_background(key.clone(), every, || Ok(json!("after the claim")))["value"].clone();
            assert_ne!(shown, json!("before the claim"), "the read from before the claim came back");
            if !shown.is_null() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(50));
        }
        assert_eq!(shown, json!("after the claim"));
    }

    /// Review (4): the app can ask for the bridge network's balances afresh
    /// (`{"accounts": [...], "fresh": true}`, after a claim or a burn): the kept value stays shown
    /// while a read made now runs; a read under way is dropped.
    #[test]
    fn review_the_bridge_network_balances_can_be_asked_afresh() {
        let mut names = fresh();
        let refused = parsed(&names.bridge_net_balances(json!({ "accounts": ["Public/abc"], "fresh": true }).to_string()));
        assert!(refused["error"].as_str().unwrap_or_default().contains("public account"), "the object form is read: {refused}");
        let key = format!("{BRIDGE_NET_KEY}test");
        let every = std::time::Duration::from_secs(60);
        let _ = names.read_in_background(key.clone(), every, || Ok(json!(1)));
        std::thread::sleep(std::time::Duration::from_millis(200));
        assert_eq!(names.read_in_background(key.clone(), every, || Ok(json!(2)))["value"], json!(1), "kept within its age");
        names.refresh_reads(BRIDGE_NET_KEY);
        let asked = names.read_in_background(key.clone(), every, || Ok(json!(2)));
        assert_eq!((asked["value"].clone(), asked["updating"].clone()), (json!(1), json!(true)), "the kept value shown while a read made now runs");
        std::thread::sleep(std::time::Duration::from_millis(200));
        assert_eq!(names.read_in_background(key, every, || Ok(json!(3)))["value"], json!(2));
    }

    #[test]
    fn chain_send_plans_then_sends_and_refuses_overdrafts() {
        let mut names = fresh();
        let to = "ab".repeat(32);
        node_answers("wallet_get_balance", json!("5000"));
        node_answers("wallet_get_notes", json!({ "notes": [{ "id": "b271", "value": "5000" }] }));
        node_answers("wallet_transfer_funds", json!("cd".repeat(32)));
        node_answers("get_transaction", json!({ "mantle_tx": { "ops": [{ "opcode": 0, "payload": { "inputs": ["b271"], "outputs": [{ "value": 1000 }, { "value": 3946 }] } }] } }));
        let plan = parsed(&names.chain_send(NODE_KEY.into(), to.clone(), "1,000".into(), false));
        assert_eq!(plan["value"]["amount"], "1000", "{plan}");
        assert_eq!(plan["value"]["hash"], Value::Null, "a plan sends nothing");
        assert!(!node_asked().contains(&"wallet_transfer_funds".to_owned()));
        let sent = parsed(&names.chain_send(NODE_KEY.into(), to.clone(), "1000".into(), true));
        assert_eq!(sent["value"]["hash"], "cd".repeat(32), "{sent}");
        assert_eq!(sent["value"]["fee"], "54", "5000 in, 1000 + 3946 out");
        // Pending while its input is still in the wallet, in a block once it's gone.
        assert_eq!(parsed(&names.chain_tx("cd".repeat(32)))["value"]["state"], "pending");
        node_answers("wallet_get_notes", json!({ "notes": [{ "id": "c0de", "value": "3946" }] }));
        let landed = parsed(&names.chain_tx("cd".repeat(32)));
        assert_eq!(landed["value"], json!({ "hash": "cd".repeat(32), "state": "in_block", "fee": "54" }));
        // The module reloaded (a verifier's find: the send was held in memory only).
        let mut reloaded = fresh();
        assert_eq!(parsed(&reloaded.chain_tx("cd".repeat(32)))["value"], landed["value"], "a send is followed after a restart");
        let asked = node::ASKED.with(|asked| asked.borrow().iter().find(|(m, _)| m == "wallet_transfer_funds").map(|(_, a)| a.clone()));
        assert_eq!(asked, Some(json!([NODE_KEY, [NODE_KEY], to, "1000", ""])), "change goes back to the sender");
        let over = parsed(&names.chain_send(NODE_KEY.into(), "ab".repeat(32), "5001".into(), true));
        assert_eq!(over["success"], false);
        assert!(over["error"].as_str().unwrap().contains("less than 5001"), "{over}");
    }

