    #[test]
    fn the_lez04_tool_is_used_only_when_its_hash_checks_and_only_on_lez04() {
        use sha2::{Digest, Sha256};
        use std::os::unix::fs::PermissionsExt;
        let (mut names, dir) = with_fake_cli("tool04", "true");
        let tool = dir.join("names-lez04");
        std::fs::write(&tool, "#!/bin/sh\necho 'names 0.17.0 (LEZ v0.4.0-rc3)'\n").unwrap();
        std::fs::set_permissions(&tool, std::fs::Permissions::from_mode(0o755)).unwrap();
        let sha: String = Sha256::digest(std::fs::read(&tool).unwrap()).iter().map(|b| format!("{b:02x}")).collect();
        names.cli = None;
        // On LEZ 0.3, never.
        LEZ04_TOOL_SHA_TEST.with(|s| *s.borrow_mut() = sha.clone());
        assert_eq!(names.adopt_lez04_tool(&tool), None);
        names.net = Net::Lez04;
        // A wrong hash: never set, never run.
        LEZ04_TOOL_SHA_TEST.with(|s| *s.borrow_mut() = "0".repeat(64));
        assert_eq!(names.adopt_lez04_tool(&tool), None);
        assert_eq!(names.cli, None);
        // The right one: set as LEZ 0.4's tool.
        LEZ04_TOOL_SHA_TEST.with(|s| *s.borrow_mut() = sha.clone());
        assert_eq!(names.adopt_lez04_tool(&tool).as_deref(), Some("names 0.17.0 (LEZ v0.4.0-rc3)"));
        assert_eq!(names.cli.as_deref(), tool.to_str());
        assert!(lez04_install_problem("no build for Linux/x86_64", false).contains("Apple silicon"));
        assert!(lez04_install_problem("could not download the LEZ 0.4 names tool", false).contains("network"));
        assert!(lez04_install_problem("the download's SHA-256 is 1, not 2", false).contains("didn't match"));
        LEZ04_TOOL_SHA_TEST.with(|s| *s.borrow_mut() = LEZ04_TOOL_SHA256.to_owned());
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// cli_install_bundled: the tool the Names app ships goes into bin/names-lez04 only on LEZ 0.4,
    /// only when no tool is set, only when its SHA-256 checks and it says LEZ 0.4; cli_status then
    /// says what it can do here (prover-status).
    #[test]
    fn the_shipped_lez04_tool_is_installed_only_when_none_is_set() {
        use sha2::{Digest, Sha256};
        use std::os::unix::fs::PermissionsExt;
        let (mut names, dir) = with_fake_cli("bundled04", "true");
        let shipped = dir.join("app").join("qml").join("bundled");
        std::fs::create_dir_all(&shipped).unwrap();
        let tool = shipped.join("names-lez04");
        std::fs::write(&tool, "#!/bin/sh\ncase \"$1\" in prover-status) echo '{\"run\":false,\"prove\":false,\"bare\":true,\"unchecked_max_fee\":{\"register\":\"4455000\"}}' ;; *) echo 'names 0.17.0 (LEZ v0.4.0-rc3)' ;; esac\n").unwrap();
        std::fs::set_permissions(&tool, std::fs::Permissions::from_mode(0o755)).unwrap();
        let sha: String = Sha256::digest(std::fs::read(&tool).unwrap()).iter().map(|b| format!("{b:02x}")).collect();
        names.bin_dir = Some(dir.join("bin"));
        names.cli = None;
        as_caller(logos_rust_sdk::LogosCaller::HostAnchor);
        let path = tool.to_string_lossy().into_owned();
        // Not on LEZ 0.3.
        assert!(parsed(&names.cli_install_bundled(path.clone(), sha.clone()))["error"].as_str().unwrap_or_default().contains("LEZ 0.4"));
        names.net = Net::Lez04;
        // A wrong checksum: nothing installed, nothing set.
        let wrong = parsed(&names.cli_install_bundled(path.clone(), "0".repeat(64)));
        assert!(wrong["error"].as_str().unwrap_or_default().contains("checksum"), "{wrong}");
        assert!(!dir.join("bin").join("names-lez04").exists() && names.cli.is_none());
        // Only a file called names-lez04.
        let other = dir.join("names");
        assert!(parsed(&names.cli_install_bundled(other.to_string_lossy().into_owned(), sha.clone()))["error"].as_str().unwrap_or_default().contains("isn't the names tool"));
        // The right one: copied, executable, set, and cli_status says it is bare.
        let done = parsed(&names.cli_install_bundled(path.clone(), sha.clone()));
        assert_eq!(done["value"]["installed"], true, "{done}");
        let ours = dir.join("bin").join("names-lez04");
        assert_eq!(names.cli.as_deref(), ours.to_str());
        assert_eq!(std::fs::metadata(&ours).unwrap().permissions().mode() & 0o777, 0o755);
        assert_eq!(done["value"]["version"], "names 0.17.0 (LEZ v0.4.0-rc3)");
        let status = parsed(&names.cli_status());
        assert_eq!(status["value"]["tool"]["bare"], true, "{status}");
        assert_eq!(status["value"]["tool"]["unchecked_max_fee"]["register"], "4455000");
        // A tool already set is kept, even another one.
        names.cli = Some(other.to_string_lossy().into_owned());
        let kept = parsed(&names.cli_install_bundled(path, sha));
        assert_eq!((kept["value"]["installed"].clone(), kept["value"]["kept"].clone()), (json!(false), json!(other.to_string_lossy())), "{kept}");
        assert!(parsed(&names.get_config())["features"].as_array().unwrap().contains(&json!("bundled_tool")));
        // Only the Names app.
        as_caller(logos_rust_sdk::LogosCaller::Module { name: "evil_ui".into(), instance: None });
        assert_eq!(parsed(&names.cli_install_bundled("x".into(), "y".into()))["success"], false);
        as_caller(logos_rust_sdk::LogosCaller::HostAnchor);
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// On an added zone, a backup still takes home's wallet for the network (review M1), says
    /// which folder went in, and its check compares with home's.
    #[test]
    fn a_backup_made_on_an_added_zone_holds_homes_wallet() {
        let (mut names, dir, second) = with_two_zones("backup-zone", "exit 0");
        let home_wallet = std::path::PathBuf::from(names.cli_wallet.clone().unwrap());
        std::fs::write(home_wallet.join(cli::STORAGE_FILE), json!({ "key_chain": { "accounts": [
            { "Public": { "account_id": "CCVd76Tk3WvFb63Wbuu4exMeLRTbSuMWHqxuvysapKnk", "data": {} } } ] } }).to_string()).unwrap();
        use_zone(&mut names, &second);
        let zone_wallet = std::path::PathBuf::from(names.cli_wallet.clone().unwrap());
        assert_ne!(zone_wallet, home_wallet);
        std::fs::write(zone_wallet.join(cli::STORAGE_FILE), json!({ "key_chain": { "accounts": [
            { "Public": { "account_id": "7wx3U7qMRWopjKXH67t9WpuNiNyB12pXUhB6CNA1LznR", "data": {} } } ] } }).to_string()).unwrap();
        as_caller(logos_rust_sdk::LogosCaller::HostAnchor);
        let file = dir.join("zone-out").join("b.lnsbackup");
        let made = parsed(&names.backup_make("lez-0.3".into(), "a long password".into(), file.to_string_lossy().into_owned()));
        assert_eq!(made["success"], true, "{made}");
        assert_eq!(made["value"]["folders"][0]["folder"], home_wallet.display().to_string(), "{made}");
        assert_eq!(made["value"]["check"]["networks"][0]["accounts"][0]["account"], "Public/CCVd76Tk3WvFb63Wbuu4exMeLRTbSuMWHqxuvysapKnk", "home's account, not the zone's");
        assert_eq!(made["value"]["check"]["networks"][0]["matches"], true, "{made}");
        // A live file the backup lacks, or an unreadable folder, is never a match.
        std::fs::write(home_wallet.join("extra.json"), "{}").unwrap();
        let checked = parsed(&names.backup_check(file.to_string_lossy().into_owned(), "a long password".into()));
        assert_eq!(checked["value"]["networks"][0]["matches"], false, "{checked}");
        assert_eq!(checked["value"]["networks"][0]["differs"], json!(["extra.json"]));
        zone_test_end(dir);
    }

    #[test]
    fn a_wallet_backup_round_trips_through_the_module_and_never_over_a_wallet() {
        let (mut names, dir) = with_fake_cli("backup", "true");
        let wallet = dir.join("wallet");
        let store = json!({ "key_chain": { "accounts": [
            { "Public": { "account_id": "CCVd76Tk3WvFb63Wbuu4exMeLRTbSuMWHqxuvysapKnk", "data": { "k": "MARKER-b4c1-key" } } },
            { "ImportedPublic": { "account_id": "7wx3U7qMRWopjKXH67t9WpuNiNyB12pXUhB6CNA1LznR", "pub_sign_key": "MARKER-b4c1-key" } } ] } });
        std::fs::write(wallet.join(cli::STORAGE_FILE), store.to_string()).unwrap();
        std::fs::write(wallet.join("wallet_config.json"), "{}").unwrap();
        let status = parsed(&names.backup_status());
        let here = status["value"]["networks"].as_array().unwrap().iter().find(|n| n["id"] == "lez-0.3").unwrap().clone();
        assert_eq!((here["has_wallet"].as_bool(), here["uncovered"].as_u64()), (Some(true), Some(1)), "{status}");
        assert_eq!(here["accounts"][0]["account"], "Public/CCVd76Tk3WvFb63Wbuu4exMeLRTbSuMWHqxuvysapKnk");
        let file = dir.join("out").join("b.lnsbackup");
        let made = parsed(&names.backup_make("lez-0.3".into(), "a long password".into(), file.to_string_lossy().into_owned()));
        assert_eq!(made["success"], true, "{made}");
        assert_eq!(made["value"]["check"]["networks"][0]["matches"], true, "checked at once: {made}");
        assert!(!made.to_string().contains("a long password") && !made.to_string().contains("MARKER-b4c1"), "nothing secret in the reply");
        assert!(!std::fs::read(&file).unwrap().windows(15).any(|w| w == b"MARKER-b4c1-key"));
        assert_eq!(parsed(&names.backup_check(file.to_string_lossy().into_owned(), "wrong password".into()))["success"], false);
        // A wallet there: shown, and never written over.
        let opened = parsed(&names.backup_open(file.to_string_lossy().into_owned(), "a long password".into()));
        assert_eq!(opened["value"]["networks"][0]["can_restore"], false, "{opened}");
        let refused = parsed(&names.backup_restore(file.to_string_lossy().into_owned(), "a long password".into(), "lez-0.3".into()));
        assert!(refused["error"].as_str().unwrap().contains("already"), "{refused}");
        // Into an empty folder: the same bytes back.
        let moved = dir.join("wallet-was");
        std::fs::rename(&wallet, &moved).unwrap();
        let restored = parsed(&names.backup_restore(file.to_string_lossy().into_owned(), "a long password".into(), "lez-0.3".into()));
        assert_eq!(restored["success"], true, "{restored}");
        for name in [cli::STORAGE_FILE, "wallet_config.json"] {
            assert_eq!(std::fs::read(wallet.join(name)).unwrap(), std::fs::read(moved.join(name)).unwrap(), "{name}");
        }
        // Another app gets nothing.
        as_caller(logos_rust_sdk::LogosCaller::Module { name: "evil_ui".into(), instance: None });
        for answer in [names.backup_status(), names.backup_open(file.to_string_lossy().into_owned(), "a long password".into()),
                       names.backup_make("lez-0.3".into(), "a long password".into(), String::new()),
                       names.backup_check(file.to_string_lossy().into_owned(), "a long password".into()),
                       names.backup_restore(file.to_string_lossy().into_owned(), "a long password".into(), "lez-0.3".into())] {
            assert!(answer.contains("only the Names app"), "{answer}");
        }
        as_caller(logos_rust_sdk::LogosCaller::HostAnchor);
        assert_eq!(stamp(1_794_700_200), "20261114-2350");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn the_registry_counts_as_absent_only_from_a_list_that_was_read_for_sure() {
        let list = json!([{ "name": "package_manager" }, { "name": "names", "version": "0.17.0" }]);
        assert_eq!(package_listed(&list, "program_registry"), Some(false));
        let with = json!([{ "name": "names" }, { "name": "program_registry" }]);
        assert_eq!(package_listed(&with, "program_registry"), Some(true));
        // As the host hands it: JSON text, perhaps twice, perhaps in {success, value}.
        assert_eq!(package_listed(&Value::from(list.to_string()), "program_registry"), Some(false));
        assert_eq!(package_listed(&Value::from(Value::from(list.to_string()).to_string()), "program_registry"), Some(false));
        assert_eq!(package_listed(&json!({ "success": true, "value": list }), "program_registry"), Some(false));
        // Anything else is unknown, never "not installed": asked as before.
        assert_eq!(package_listed(&json!([]), "program_registry"), None);
        assert_eq!(package_listed(&json!([{ "name": "chat_module" }]), "program_registry"), None);
        assert_eq!(package_listed(&json!({ "error": "timeout" }), "program_registry"), None);
        assert_eq!(package_listed(&Value::from("not json"), "program_registry"), None);
        assert_eq!(package_listed(&Value::Null, "program_registry"), None);
    }

    /// Another app reads `features` from get_config (`value.features` in the envelope): every
    /// feature PROVIDER-SDK.md names, and every one this build has. Until 3434018 only the Names
    /// app saw them, so no app ever sent an account hint (M2, 2026-11-14).
    #[test]
    fn another_app_sees_every_documented_feature() {
        let mut names = fresh();
        as_caller(logos_rust_sdk::LogosCaller::Module { name: "lez_bridge".into(), instance: None });
        let seen = parsed(&names.get_config());
        as_caller(logos_rust_sdk::LogosCaller::HostAnchor);
        assert_eq!(seen["success"], true, "{seen}");
        let features: Vec<&str> = seen["value"]["features"].as_array().unwrap_or_else(|| panic!("no features for another app: {seen}")).iter().filter_map(Value::as_str).collect();
        assert_eq!(features, MODULE_FEATURES.to_vec());
        // Each feature the SDK document tells apps to check is one they see.
        let doc = include_str!("../../../docs/wallet/PROVIDER-SDK.md");
        let documented: Vec<&str> = doc.split("features` for `\"").skip(1).filter_map(|rest| rest.split('"').next()).collect();
        assert!(documented.contains(&"request_access_with") && documented.contains(&"grant_add_account"), "{documented:?}");
        for feature in documented {
            assert!(features.contains(&feature), "PROVIDER-SDK.md names {feature}, which another app doesn't see in get_config");
        }
        // It says it implements the Names Wallet SDK (an app's listWallets reads this).
        assert_eq!(seen["value"]["wallet_sdk"], json!({ "name": "names-wallet", "version": WALLET_SDK_VERSION, "app": "names_ui" }));
        // Nothing beyond the network part and the features: no paths, wallet or CLI.
        for private in ["cli", "cli_wallet", "wallet_config", "wallet_storage", "main_name", "memory_bytes"] {
            assert!(seen["value"].get(private).is_none(), "{private} must stay with the Names app");
        }
    }

    /// The view settings outlive the module (a file, unlike app_note), are the Names app's
    /// own, and stay small.
    #[test]
    fn app_settings_are_kept_and_the_names_apps_own() {
        let mut names = fresh();
        as_caller(logos_rust_sdk::LogosCaller::HostAnchor);
        let _ = std::fs::remove_file(config_dir().unwrap().join(APP_SETTINGS_FILE));
        assert_eq!(parsed(&names.app_settings())["value"], json!({}));
        assert_eq!(parsed(&names.app_setting("fold_bridging".into(), "yes".into()))["value"], "");
        assert_eq!(parsed(&names.app_setting("hidden_send_backs".into(), "[\"sb-6163f4e0007b40e3\"]".into()))["value"], "");
        // A new module (Basecamp started again) reads them back from the file.
        let mut again = fresh();
        assert_eq!(parsed(&again.app_settings())["value"], json!({ "fold_bridging": "yes", "hidden_send_backs": "[\"sb-6163f4e0007b40e3\"]" }));
        assert_eq!(parsed(&again.app_setting("fold_bridging".into(), "".into()))["value"], "yes");
        assert_eq!(parsed(&again.app_settings())["value"], json!({ "hidden_send_backs": "[\"sb-6163f4e0007b40e3\"]" }));
        assert_eq!(parsed(&again.app_setting(" ".into(), "x".into()))["success"], false);
        assert_eq!(parsed(&again.app_setting("k".into(), "x".repeat(APP_SETTING_MAX + 1)))["success"], false);
        for i in 0..APP_SETTINGS_MAX - 1 {
            assert_eq!(parsed(&again.app_setting(format!("k{i}"), "x".into()))["success"], true);
        }
        assert_eq!(parsed(&again.app_setting("one_more".into(), "x".into()))["success"], false);
        assert_eq!(parsed(&again.app_setting("k0".into(), "y".into()))["value"], "x", "a key it has can change");
        assert!(parsed(&again.get_config())["features"].as_array().unwrap().contains(&json!("app_settings")));
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = std::fs::metadata(config_dir().unwrap().join(APP_SETTINGS_FILE)).unwrap().permissions().mode();
            assert_eq!(mode & 0o777, 0o600);
        }
        as_caller(logos_rust_sdk::LogosCaller::Module { name: "lez_bridge".into(), instance: None });
        assert_eq!(parsed(&again.app_settings())["success"], false, "only the Names app");
        assert_eq!(parsed(&again.app_setting("k0".into(), "".into()))["success"], false, "only the Names app");
        as_caller(logos_rust_sdk::LogosCaller::HostAnchor);
        let _ = std::fs::remove_file(config_dir().unwrap().join(APP_SETTINGS_FILE));
    }

